window.CHAPTERS=window.CHAPTERS||{};window.CHAPTERS["ch06"]={"id": "ch06", "title": "第六章 转录组学", "sub": "陈铭《生物信息学》第三版 · 科学出版社", "sub2": "复试生物信息学 · 逐章详解", "modules": [{"i": 0, "name": "第六章 转录组学", "slides": [{"i": 0, "sec": "第一节 转录组学概述", "title": "中心法则与转录组学定义", "notes": "中心法则由Crick于1958年提出，描述遗传信息从DNA经RNA传递至蛋白质的流向。DNA、RNA、蛋白质三个层次分别衍生出基因组学、转录组学和蛋白质组学。转录组学（transcriptomics）在20世纪90年代提出，研究对象是全基因组尺度下所有转录本（transcript），即转录组（transcriptome）。广义上转录组指细胞中所有RNA分子的总和，包括mRNA、rRNA、tRNA、ncRNA等，但有时特指mRNA。本章探讨的转录本无特殊说明则专指mRNA。转录组学从RNA水平研究基因表达情况，系统性地揭示细胞中基因转录调控规律，弥补了基因组学难以直接解释生命活动和蛋白质研究技术不完善的局限。", "page": 102, "level": "掌握", "img": "assets/img/ch06/p102.jpg", "anim": null, "fig": null, "points": ["中心法则由Crick于1958年提出，描述遗传信息从DNA经RNA传递至蛋白质的流向。", "DNA、RNA、蛋白质三个层次分别衍生出基因组学、转录组学和蛋白质组学。", "转录组学（transcriptomics）在20世纪90年代提出，研究对象是全基因组尺度下所有转录本（transcript），即转录组（transcriptome）。", "广义上转录组指细胞中所有RNA分子的总和，包括mRNA、rRNA、tRNA等。"], "check": {"q": "关于中心法则与转录组学，下列说法正确的是？", "o": ["A. 中心法则由Watson于1953年提出，描述遗传信息从DNA到RNA再到蛋白质的流向", "B. 转录组学在20世纪90年代提出，研究对象是全基因组尺度下所有转录本", "C. 转录组广义上仅指细胞中所有mRNA分子的总和", "D. 基因组学、转录组学和蛋白质组学分别对应RNA、DNA、蛋白质三个层次"], "a": "B", "e": "中心法则由Crick于1958年提出；转录组学在20世纪90年代提出，研究对象是全基因组尺度下所有转录本；广义转录组包括mRNA、rRNA、tRNA、ncRNA等，有时特指mRNA；基因组学、转录组学和蛋白质组学分别对应DNA、RNA、蛋白质三个层次。"}, "cards": [{"front": "中心法则由谁提出？其内容是什么？", "back": "中心法则由Crick于1958年提出，描述遗传信息从DNA经RNA传递至蛋白质的流向。", "mnemonic": "DNA→RNA→蛋白质", "useImg": false}, {"front": "转录组学的定义是什么？", "back": "转录组学（transcriptomics）在20世纪90年代提出，研究对象是全基因组尺度下所有转录本（transcript），即转录组（transcriptome）。广义上转录组指细胞中所有RNA分子的总和，包括mRNA、rRNA、tRNA等。", "mnemonic": "", "useImg": false}]}, {"i": 1, "sec": "第一节 转录组学概述", "title": "转录本测定技术演进", "notes": "单一转录本测定技术早期包括Northern blotting和RT-PCR，精准但通量低、价格昂贵。1980年后基于Sanger测序的EST、SAGE、CAGE、MPSS等技术提高了通量并具备一定定量能力，但价格仍高，在读段匹配率和转录本异构体鉴定方面存在不足。基于杂交的基因芯片技术将荧光标记的cDNA制成微阵列探针，通量较高、价格相对较低，但需参考转录组信息，存在交叉杂交背景噪声、低表达丰度基因检测困难、荧光信号动态检测范围有限等缺陷。基于第二代测序的RNA-seq带来历史性变革，不依赖参考基因组，可直接测定转录本序列和含量，通量极高，成本日益降低。", "page": 103, "level": "理解", "img": "assets/img/ch06/p103.jpg", "anim": null, "fig": null, "points": ["RNA-seq与基因芯片在多方面存在差异：通量方面，基因芯片较低，RNA-seq高。", "最低RNA含量方面，基因芯片约1μg，RNA-seq约1ng。", "参考基因组方面，基因芯片必需，RNA-seq非必要。", "定量精确度两者均约90%。", "灵敏度方面，基因芯片约10^3—10^4，RNA-seq约10^3—10^4。", "动态范围方面，基因芯片依赖于荧光信号，RNA-seq依赖于测序深度。", "RNA-seq具有不依赖参考基因组等优势。"], "check": {"q": "关于转录本测定技术演进，下列描述错误的是？", "o": ["A. Northern blotting和RT-PCR可精准测定单一转录本，但通量低、价格昂贵", "B. EST、SAGE、CAGE、MPSS等基于Sanger测序的技术提高了通量并具备一定定量能力", "C. 基因芯片技术通量较高、价格相对较低，且不需要参考转录组信息", "D. 基因芯片存在交叉杂交背景噪声、低表达丰度基因检测困难等缺陷"], "a": "C", "e": "基因芯片需要参考转录组信息，并存在交叉杂交背景噪声、低表达丰度基因检测困难、荧光信号动态检测范围有限等缺陷。"}, "cards": [{"front": "早期单一转录本测定技术有哪些？", "back": "早期包括Northern blotting和RT-PCR，精准但通量低、价格昂贵。", "mnemonic": "", "useImg": false}, {"front": "基于Sanger测序的转录本测定技术有哪些？", "back": "1980年后基于Sanger测序的EST、SAGE、CAGE、MPSS等技术提高了通量并具备一定定量能力，但价格仍高，在读段匹配率和转录本异构体鉴定方面存在不足。", "mnemonic": "", "useImg": false}, {"front": "基因芯片技术的原理和优缺点是什么？", "back": "基于杂交的基因芯片技术将荧光标记的cDNA制成微阵列探针，通量较高、价格相对较低，但需参考转录组信息，存在交叉杂交背景噪声、低表达丰度基因检测困难等缺点。", "mnemonic": "", "useImg": false}, {"front": "RNA-seq与基因芯片在通量和最低RNA含量方面有何差异？", "back": "通量方面，基因芯片较低，RNA-seq高。最低RNA含量方面，基因芯片约1μg，RNA-seq约1ng。", "mnemonic": "", "useImg": false}, {"front": "RNA-seq与基因芯片在参考基因组和定量精确度方面有何差异？", "back": "参考基因组方面，基因芯片必需，RNA-seq非必要。定量精确度两者均约90%。", "mnemonic": "", "useImg": false}]}, {"i": 2, "sec": "第一节 转录组学概述", "title": "RNA-seq与基因芯片比较", "notes": "RNA-seq与基因芯片在多方面存在差异。通量方面，基因芯片较低，RNA-seq高。最低RNA含量方面，基因芯片约1μg，RNA-seq约1ng。参考基因组方面，基因芯片必需，RNA-seq非必要。定量精确度两者均约90%。灵敏度方面，基因芯片约10^3—10^4，RNA-seq约10^3—10^4。动态范围方面，基因芯片依赖于荧光信号，RNA-seq依赖于测序深度。RNA-seq具有不依赖参考基因组、可直接测定转录本序列和含量、通量极高、成本越来越趋向大众化等优势。自2008年Nagalakshmi等首次使用RNA-seq技术揭示酵母基因组转录概况以来，RNA-seq在生物学研究中得到日益广泛的应用。", "page": 103, "level": "理解", "img": "assets/img/ch06/p103.jpg", "anim": null, "fig": null, "points": ["RNA-seq与基因芯片在多方面存在差异：通量方面，基因芯片较低，RNA-seq高。", "最低RNA含量方面，基因芯片约1μg，RNA-seq约1ng。", "参考基因组方面，基因芯片必需，RNA-seq非必要。", "定量精确度两者均约90%。", "灵敏度方面，基因芯片约10^3—10^4，RNA-seq约10^3—10^4。", "动态范围方面，基因芯片依赖于荧光信号，RNA-seq依赖于测序深度。", "RNA-seq具有不依赖参考基因组等优势。"], "check": {"q": "关于RNA-seq与基因芯片的比较，下列说法正确的是？", "o": ["A. 基因芯片通量高，RNA-seq通量较低", "B. 基因芯片最低RNA含量约1ng，RNA-seq约1μg", "C. RNA-seq不依赖参考基因组，可直接测定转录本序列和含量", "D. 基因芯片灵敏度约10^3—10^4，RNA-seq灵敏度明显低于基因芯片"], "a": "C", "e": "RNA-seq通量高，基因芯片通量较低；基因芯片最低RNA含量约1μg，RNA-seq约1ng；RNA-seq不依赖参考基因组，可直接测定转录本序列和含量；两者灵敏度均约10^3—10^4。"}, "cards": [{"front": "早期单一转录本测定技术有哪些？", "back": "早期包括Northern blotting和RT-PCR，精准但通量低、价格昂贵。", "mnemonic": "", "useImg": false}, {"front": "基于Sanger测序的转录本测定技术有哪些？", "back": "1980年后基于Sanger测序的EST、SAGE、CAGE、MPSS等技术提高了通量并具备一定定量能力，但价格仍高，在读段匹配率和转录本异构体鉴定方面存在不足。", "mnemonic": "", "useImg": false}, {"front": "基因芯片技术的原理和优缺点是什么？", "back": "基于杂交的基因芯片技术将荧光标记的cDNA制成微阵列探针，通量较高、价格相对较低，但需参考转录组信息，存在交叉杂交背景噪声、低表达丰度基因检测困难等缺点。", "mnemonic": "", "useImg": false}, {"front": "RNA-seq与基因芯片在通量和最低RNA含量方面有何差异？", "back": "通量方面，基因芯片较低，RNA-seq高。最低RNA含量方面，基因芯片约1μg，RNA-seq约1ng。", "mnemonic": "", "useImg": false}, {"front": "RNA-seq与基因芯片在参考基因组和定量精确度方面有何差异？", "back": "参考基因组方面，基因芯片必需，RNA-seq非必要。定量精确度两者均约90%。", "mnemonic": "", "useImg": false}]}, {"i": 3, "sec": "第二节 试验设计和测序流程", "title": "RNA-seq试验设计要点", "notes": "RNA-seq实验前需考虑多个问题。生物学重复：没有重复难以排除随机误差，过多重复增加成本，一般3~5个，假阳性控制要求高时可适当增加。样本提取：控制干扰变量及避免人为误差，注意提取时间和组织细胞的控制，提取后及时冷冻保存。测序深度：有参考基因组且不进行可变剪切或新转录本分析时，每个样本最少5M有效reads（ENCODE推荐）；鉴定新转录本或无参考基因组时需适当增加；small RNA一般需要30M以上有效匹配reads。文库构建：链特异性文库保留转录本方向信息，避免互补链干扰，基因表达定量和可变剪切鉴别更准确，但价格更高。测序策略：单末端测序更快、价格低，一般足够定量；双末端测序产生成对reads，有利于基因注释和转录本异构体发现。", "page": 105, "level": "掌握", "img": "assets/img/ch06/p105.jpg", "anim": null, "fig": null, "points": ["RNA-seq实验前需考虑多个问题：生物学重复：没有重复难以排除随机误差，过多重复增加成本，一般3~5个，假阳性控制要求高时可适当增加。", "样本提取：控制干扰变量及避免人为误差，注意提取时间和组织细胞的控制，提取后及时冷冻保存。", "测序深度：有参考基因组且不进行可变剪切或新转录本分析时，每个样本最少5M有效reads（ENCODE推荐）；鉴定新转录本或无参考基因组时需适当增加；small RNA一般需要3M reads。"], "check": {"q": "关于RNA-seq试验设计要点，下列说法错误的是？", "o": ["A. 没有生物学重复难以排除随机误差，一般建议3~5个重复", "B. 有参考基因组且不进行可变剪切或新转录本分析时，每个样本最少5M有效reads", "C. small RNA测序一般需要30M以上有效匹配reads", "D. 样本提取后应尽快室温保存，以保持RNA完整性"], "a": "D", "e": "样本提取后应及时冷冻保存，而不是室温保存；其余关于重复数、测序深度和small RNA reads数的描述均正确。"}, "cards": [{"front": "RNA-seq实验设计中生物学重复一般需要多少个？", "back": "一般3~5个，假阳性控制要求高时可适当增加。", "mnemonic": "", "useImg": false}, {"front": "RNA-seq实验设计中测序深度如何确定？", "back": "有参考基因组且不进行可变剪切或新转录本分析时，每个样本最少5M有效reads（ENCODE推荐）；鉴定新转录本或无参考基因组时需适当增加；small RNA一般需要3M reads。", "mnemonic": "", "useImg": false}]}, {"i": 4, "sec": "第二节 试验设计和测序流程", "title": "常用测序平台比较", "notes": "常用测序平台包括454、Illumina、SOLID、Ion Torrent等。454于2005年发布，读长700bp，单次最大通量0.7Gbp，read准确率99.9%，NCBI SRA run数量3548。Illumina于2006年发布，读长50~300bp，单次最大通量900Gbp，read准确率99.9%，NCBI SRA run数量362903。SOLID于2008年发布，读长50bp，单次最大通量320Gbp，read准确率99.9%，NCBI SRA run数量7032。Ion Torrent于2010年发布，读长400bp，单次最大通量30Gbp，read准确率98%，NCBI SRA run数量1953。测序平台选择依赖于实验及后续分析需要，考虑测序读长、最大测序通量、测序准确率等指标。", "page": 106, "level": "了解", "img": "assets/img/ch06/p106.jpg", "anim": null, "fig": null, "points": ["RNA测序流程：选择感兴趣样本提取RNA，采用PolyA富集或rRNA移除策略分离纯化RNA，随机打碎成短片段并反转录为cDNA，选择合适长度片段添加接头构建文库，扩增并测序。", "cDNA文库制备三个关键步骤：总RNA提取，将RNA从特定组织分离并与DNase混合降解DNA，用凝胶和毛细管电泳检测RNA降解量评估质量；", "RNA分离纯化，成熟mRNA具有3' PolyA尾，可通过PolyT低聚物磁珠富集。"], "check": {"q": "关于常用测序平台比较，下列说法正确的是？", "o": ["A. 454于2005年发布，读长700bp，单次最大通量0.7Gbp", "B. Illumina于2008年发布，读长50bp，单次最大通量320Gbp", "C. SOLID于2006年发布，读长50~300bp，单次最大通量900Gbp", "D. Ion Torrent读长最长，单次最大通量最高"], "a": "A", "e": "454于2005年发布，读长700bp，单次最大通量0.7Gbp；Illumina于2006年发布，读长50~300bp，单次最大通量900Gbp；SOLID于2008年发布，读长50bp，单次最大通量320Gbp。"}, "cards": [{"front": "常用测序平台有哪些？", "back": "常用测序平台包括454、Illumina、SOLID、Ion Torrent等。", "mnemonic": "", "useImg": false}, {"front": "Illumina测序平台的主要参数是什么？", "back": "Illumina于2006年发布，读长50~300bp，单次最大通量900Gbp，read准确率99.9%，NCBI SRA run数量362903。", "mnemonic": "", "useImg": false}, {"front": "RNA-seq文库制备流程包括哪些步骤？", "back": "选择感兴趣样本提取RNA，采用PolyA富集或rRNA移除策略分离纯化RNA，随机打碎成短片段并反转录为cDNA，选择合适长度片段添加接头构建文库，扩增并测序。", "mnemonic": "", "useImg": false}, {"front": "cDNA文库制备的三个关键步骤是什么？", "back": "总RNA提取，将RNA从特定组织分离并与DNase混合降解DNA，用凝胶和毛细管电泳检测RNA降解量评估质量；RNA分离纯化，成熟mRNA具有3' PolyA尾，可通过PolyT低聚物磁珠富集。", "mnemonic": "", "useImg": false}]}, {"i": 5, "sec": "第二节 试验设计和测序流程", "title": "RNA-seq文库制备流程", "notes": "RNA测序流程：选择感兴趣样本提取RNA，采用PolyA富集或rRNA移除策略分离纯化RNA，随机打碎成短片段并反转录为cDNA，选择合适长度片段添加接头构建文库，扩增并测序。cDNA文库制备三个关键步骤：总RNA提取，将RNA从特定组织分离并与DNase混合降解DNA，用凝胶和毛细管电泳检测RNA降解量评估质量；RNA分离纯化，成熟mRNA具有3' PolyA尾，可通过PolyT低聚物磁珠富集，PolyA富集忽略非编码RNA并引入3'偏倚，rRNA移除策略可避免这些问题，rRNA占总RNA比例超过90%，移除后可留下目标序列；cDNA合成，RNA无法直接测序，需打碎成片段并逆转录为cDNA，打碎可采用酶、超声波或喷雾器，片段化降低随机引物逆转录的5'偏倚，逆转录会导致方向性缺失，通过化学标记可保留方向信息（链特异性文库），末端修复加接头，按长度排序分类，选择适当长度PCR扩增纯化，检测文库质量后上机测序。", "page": 106, "level": "掌握", "img": "assets/img/ch06/p106.jpg", "anim": null, "fig": null, "points": ["RNA测序流程：选择感兴趣样本提取RNA，采用PolyA富集或rRNA移除策略分离纯化RNA，随机打碎成短片段并反转录为cDNA，选择合适长度片段添加接头构建文库，扩增并测序。", "cDNA文库制备三个关键步骤：总RNA提取，将RNA从特定组织分离并与DNase混合降解DNA，用凝胶和毛细管电泳检测RNA降解量评估质量；", "RNA分离纯化，成熟mRNA具有3' PolyA尾，可通过PolyT低聚物磁珠富集。"], "check": {"q": "关于RNA-seq文库制备流程，下列说法错误的是？", "o": ["A. 提取RNA后可采用PolyA富集或rRNA移除策略分离纯化RNA", "B. 随机打碎RNA成短片段并反转录为cDNA", "C. 成熟mRNA具有3' PolyA尾，可通过PolyT低聚物磁珠富集", "D. PolyA富集能够保留全部非编码RNA，适合所有RNA研究"], "a": "D", "e": "PolyA富集主要富集成熟mRNA，会忽略非编码RNA，并可能引入3'端偏好，不适合所有RNA研究。"}, "cards": [{"front": "常用测序平台有哪些？", "back": "常用测序平台包括454、Illumina、SOLID、Ion Torrent等。", "mnemonic": "", "useImg": false}, {"front": "Illumina测序平台的主要参数是什么？", "back": "Illumina于2006年发布，读长50~300bp，单次最大通量900Gbp，read准确率99.9%，NCBI SRA run数量362903。", "mnemonic": "", "useImg": false}, {"front": "RNA-seq文库制备流程包括哪些步骤？", "back": "选择感兴趣样本提取RNA，采用PolyA富集或rRNA移除策略分离纯化RNA，随机打碎成短片段并反转录为cDNA，选择合适长度片段添加接头构建文库，扩增并测序。", "mnemonic": "", "useImg": false}, {"front": "cDNA文库制备的三个关键步骤是什么？", "back": "总RNA提取，将RNA从特定组织分离并与DNase混合降解DNA，用凝胶和毛细管电泳检测RNA降解量评估质量；RNA分离纯化，成熟mRNA具有3' PolyA尾，可通过PolyT低聚物磁珠富集。", "mnemonic": "", "useImg": false}]}, {"i": 6, "sec": "第三节 转录组数据核心分析", "title": "FASTQ格式与测序数据存储", "notes": "第二代测序得到长度为50~250bp的短片段，称为reads。测序仪输出的原始测序结果通常以FASTQ文件存储。FASTQ格式用于存储生物序列（通常是核苷酸序列）及其相应测序质量得分的文本文件，序列字母和质量得分都用单个ASCII字符表示。该格式最初由Wellcome Trust Sanger研究所开发，用于捆绑FASTA序列及其质量数据，现已成为存储高通量测序仪输出的实际标准。FASTQ文件中一个read通常由四行组成：第一行以@开头，之后为序列的标识符及描述信息（与FASTA格式描述行类似）；第二行为read的序列信息；第三行以+开头，可以再次添加序列描述信息（可选）；第四行为质量得分信息，与第二行序列相对应，长度必须与第二行相同。", "page": 107, "level": "掌握", "img": "assets/img/ch06/p107.jpg", "anim": null, "fig": null, "points": ["第二代测序得到长度为50~250bp的短片段，称为reads。", "测序仪输出的原始测序结果通常以FASTQ文件存储。", "FASTQ格式用于存储生物序列（通常是核苷酸序列）及其相应测序质量得分的文本文件，序列字母和质量得分都用单个ASCII字符表示。", "该格式最初由Wellcome Trust Sanger研究所开发，用于捆绑FASTA序列及其质量数据，现已成为存储高通量测序仪输出的实际标准。"], "check": {"q": "关于FASTQ格式与测序数据存储，下列说法正确的是？", "o": ["A. FASTQ文件用于存储氨基酸序列及其质量得分", "B. FASTQ格式最初由NCBI开发，用于存储Sanger测序结果", "C. FASTQ文件中一个read通常由四行组成，第一行以@开头", "D. FASTQ文件中序列字母和质量得分都用双字符表示"], "a": "C", "e": "FASTQ用于存储核苷酸序列及其测序质量得分；最初由Wellcome Trust Sanger研究所开发；一个read通常由四行组成，第一行以@开头；序列字母和质量得分都用单个ASCII字符表示。"}, "cards": [{"front": "FASTQ格式是什么？", "back": "FASTQ格式用于存储生物序列（通常是核苷酸序列）及其相应测序质量得分的文本文件，序列字母和质量得分都用单个ASCII字符表示。该格式最初由Wellcome Trust Sanger研究所开发，用于捆绑FASTA序列及其质量数据，现已成为存储高通量测序仪输出的实际标准。", "mnemonic": "", "useImg": false}]}, {"i": 7, "sec": "第三节 转录组数据核心分析", "title": "测序数据质控与预处理", "notes": "RNA-seq数据预处理包括提取fastq文件、质量评估和质量控制。使用fastq-dump工具从SRA文件中提取fastq序列文件。使用FastQC检测原始测序数据质量，关键指标包括Per base sequence quality、Per base sequence content等。若测序质量要求较高，可使用FastX_Toolkit进行质量控制。使用fastx_trimmer截去reads前12位碱基，参数-Q 33为Illumina编码转换，-f为截取起始位置，-i输入文件，-o输出文件。使用fastq_quality_filter过滤低质量reads，参数-Q同上，-q保留结果所需达到的最低得分，-p每个reads中达到-q得分的最小百分数。处理后再次质量评估，Per base sequence content等指标提升，Sequence duplication levels和Kmer Content可能仍未达标，但已可用于RNA-seq分析。", "page": 123, "level": "掌握", "img": "assets/img/ch06/p123.jpg", "anim": null, "fig": null, "points": ["使用fastq-dump工具从SRA文件中提取fastq序列文件，命令如：$ fastq-dump SRR3418005.sra &。", "对其余3个文件执行上述命令，产生的4个测序原始数据文件共计32.4GB。", "使用FastQC检测原始测序数据质量，命令如：$ fastqc -o ../fastqc_results -f fastq SRR3418005.fastq SRR3418006.fastq S。"], "check": {"q": "关于测序数据质控与预处理，下列说法错误的是？", "o": ["A. 可使用fastq-dump工具从SRA文件中提取fastq序列文件", "B. FastQC可用于检测原始测序数据质量", "C. FastX_Toolkit可用于质量控制，fastx_trimmer可截去reads前12位碱基", "D. FastQC的关键指标不包括Per base sequence quality"], "a": "D", "e": "FastQC的关键指标包括Per base sequence quality、Per base sequence content等，因此D错误。"}, "cards": [{"front": "RNA-seq数据预处理包括哪些步骤？", "back": "RNA-seq数据预处理包括提取fastq文件、质量评估和质量控制。", "mnemonic": "", "useImg": false}, {"front": "如何从SRA文件中提取fastq序列文件？", "back": "使用fastq-dump工具从SRA文件中提取fastq序列文件。", "mnemonic": "", "useImg": false}, {"front": "使用什么工具检测原始测序数据质量？关键指标有哪些？", "back": "使用FastQC检测原始测序数据质量，关键指标包括Per base sequence quality、Per base sequence content等。", "mnemonic": "", "useImg": false}, {"front": "案例中如何使用fastq-dump提取fastq文件？", "back": "使用fastq-dump工具从SRA文件中提取fastq序列文件，命令如：$ fastq-dump SRR3418005.sra &。对其余3个文件执行上述命令，产生的4个测序原始数据文件共计32.4GB。", "mnemonic": "", "useImg": false}, {"front": "案例中如何使用FastQC检测原始测序数据质量？", "back": "使用FastQC检测原始测序数据质量，命令如：$ fastqc -o ../fastqc_results -f fastq SRR3418005.fastq SRR3418006.fastq S。", "mnemonic": "", "useImg": false}]}, {"i": 8, "sec": "第三节 转录组数据核心分析", "title": "序列比对与表达定量", "notes": "RNA-seq核心分析包括序列比对和表达定量。有参考基因组时，可使用比对工具如Bowtie、HISAT2、STAR等将reads比对到参考基因组或转录组。无参考基因组时，需进行从头组装，如Trinity软件包含Inchworm、Chrysalis和Butterfly三个模块。Inchworm将RNA-seq原始reads切割为k-mers（长度为k bp的短片段），利用重叠进行延伸组装成contigs序列；Chrysalis将生成的contigs聚类，并对每个类构建de Bruijn图；Butterfly拆分de Bruijn图为线性序列，依据图中的reads和成对reads寻找最佳路径，得到具有可变剪切的全长转录本。组装完成后需评估质量，包括组装完整性、准确性及冗余度。将reads通过Bowtie重新比对到组装成的转录本上，利用HTSeq-count或RSEM等进行reads计数估算表达量，同时可通过Blast2GO等对转录本进行功能注释。", "page": 112, "level": "掌握", "img": "assets/img/ch06/p112.jpg", "anim": null, "fig": null, "points": ["差异表达分析指基于统计学模型，对不同样本处理下的基因表达差异进行分析，区分差异源于处理效应还是随机误差。", "样本选取对结果影响较大，当样本齐次性较差或样本数量较大时，需先对样本进行相关性分析，剔除异常样本，也可使用主成分分析（PCA）选取样本。", "对选定样本进行归一化、建模和统计检验是差异表达分析的主要过程。", "差异表达分析结果一般用差异倍数（fold change）和统计检验显著性值描述。"], "check": {"q": "关于序列比对与表达定量，下列说法正确的是？", "o": ["A. 有参考基因组时，可使用Bowtie、HISAT2、STAR等将reads比对到参考基因组或转录组", "B. 无参考基因组时，必须使用Bowtie进行比对", "C. Trinity软件包含Inchworm、Chrysalis和Butterfly三个模块，其中Butterfly用于切割k-mers", "D. Inchworm将contigs连接成组分，Chrysalis将reads切割为k-mers"], "a": "A", "e": "无参考基因组时需从头组装，如Trinity；Trinity中Inchworm将reads切割为k-mers并延伸组装成contigs，Chrysalis将contigs连接成组分，Butterfly处理可变剪切。"}, "cards": [{"front": "有参考基因组时，RNA-seq序列比对常用哪些工具？", "back": "有参考基因组时，可使用比对工具如Bowtie、HISAT2、STAR等将reads比对到参考基因组或转录组。", "mnemonic": "", "useImg": false}, {"front": "无参考基因组时，RNA-seq如何进行从头组装？", "back": "无参考基因组时，需进行从头组装，如Trinity软件包含Inchworm、Chrysalis和Butterfly三个模块。Inchworm将RNA-seq原始reads切割为k-mers（长度为k bp的短片段），利用重叠进行延伸组装成contig。", "mnemonic": "", "useImg": false}, {"front": "差异表达分析的定义是什么？", "back": "差异表达分析指基于统计学模型，对不同样本处理下的基因表达差异进行分析，区分差异源于处理效应还是随机误差。", "mnemonic": "", "useImg": false}, {"front": "差异表达分析中样本选取需要注意什么？", "back": "样本选取对结果影响较大，当样本齐次性较差或样本数量较大时，需先对样本进行相关性分析，剔除异常样本，也可使用主成分分析（PCA）选取样本。", "mnemonic": "", "useImg": false}]}, {"i": 9, "sec": "第四节 功能分析", "title": "差异表达分析原理与差异来源", "notes": "差异表达分析指基于统计学模型，对不同样本处理下的基因表达差异进行分析，区分差异源于处理效应还是随机误差。样本选取对结果影响较大，当样本齐次性较差或样本数量较大时，需先对样本进行相关性分析，剔除异常样本，也可使用主成分分析（PCA）选取样本。对选定样本进行归一化、建模和统计检验是差异表达分析的主要过程。差异表达分析结果一般用差异倍数（fold change）和统计检验显著性值描述。差异来源：不同实验处理引起的差异称为处理差异；同一实验条件下不同样本之间由于个体差异、技术误差等存在差异，称为组内差异。直接比较组间差异时包括组内差异和处理差异，最终检验处理效应显著性时，应由组间差异减去组内差异。计算组内差异需要生物学重复，无重复样本时差异表达分析结果可靠性下降。", "page": 112, "level": "掌握", "img": "assets/img/ch06/p112.jpg", "anim": null, "fig": null, "points": ["差异表达分析指基于统计学模型，对不同样本处理下的基因表达差异进行分析，区分差异源于处理效应还是随机误差。", "样本选取对结果影响较大，当样本齐次性较差或样本数量较大时，需先对样本进行相关性分析，剔除异常样本，也可使用主成分分析（PCA）选取样本。", "对选定样本进行归一化、建模和统计检验是差异表达分析的主要过程。", "差异表达分析结果一般用差异倍数（fold change）和统计检验显著性值描述。"], "check": {"q": "关于差异表达分析原理与差异来源，下列说法错误的是？", "o": ["A. 差异表达分析基于统计学模型，区分处理效应和随机误差", "B. 样本齐次性较差时，可先进行相关性分析剔除异常样本，也可使用PCA选取样本", "C. 差异表达分析结果一般用差异倍数和统计检验显著性值描述", "D. 同一实验条件下不同个体间的差异属于处理差异"], "a": "D", "e": "不同实验处理引起的差异称为处理差异；同一实验条件下不同个体间的差异属于随机误差或生物学变异，不是处理差异。"}, "cards": [{"front": "有参考基因组时，RNA-seq序列比对常用哪些工具？", "back": "有参考基因组时，可使用比对工具如Bowtie、HISAT2、STAR等将reads比对到参考基因组或转录组。", "mnemonic": "", "useImg": false}, {"front": "无参考基因组时，RNA-seq如何进行从头组装？", "back": "无参考基因组时，需进行从头组装，如Trinity软件包含Inchworm、Chrysalis和Butterfly三个模块。Inchworm将RNA-seq原始reads切割为k-mers（长度为k bp的短片段），利用重叠进行延伸组装成contig。", "mnemonic": "", "useImg": false}, {"front": "差异表达分析的定义是什么？", "back": "差异表达分析指基于统计学模型，对不同样本处理下的基因表达差异进行分析，区分差异源于处理效应还是随机误差。", "mnemonic": "", "useImg": false}, {"front": "差异表达分析中样本选取需要注意什么？", "back": "样本选取对结果影响较大，当样本齐次性较差或样本数量较大时，需先对样本进行相关性分析，剔除异常样本，也可使用主成分分析（PCA）选取样本。", "mnemonic": "", "useImg": false}]}, {"i": 10, "sec": "第四节 功能分析", "title": "差异表达分析模型选择", "notes": "一般测序实验的生物学重复和样本数较小，难以采用非参数检验直接进行差异分析，而参数检验基于样本总体分布信息，需假设合适模型描述分布。1. 高斯分布：最初使用高斯分布描述表达水平，然而基因表达量不可能是负值，严格意义上并不符合正态分布。2. 泊松分布：Marioni等研究发现RNA-seq技术重复条件下的测序方差与泊松分布方差相吻合。Simon等发现在生物学重复情况下，低表达基因方差符合泊松分布；随着表达量升高，实际方差远大于泊松分布方差。3. 负二项分布：Simon等指出泊松分布模型可能严重低估个体差异带来的误差，负二项分布的方差可通过调整散度因子α的值来调节模型离散度，使其符合实际情况中基因表达方差远大于均值的情况。DESeq和edgeR都采用负二项分布描述reads频数分布。4. β负二项分布：β二项分布可以拟合比对过程中的多重比对reads分配误差，与负二项分布结合而成β负二项分布，Cuffdiff采用这种分布。", "page": 113, "level": "理解", "img": "assets/img/ch06/p113.jpg", "anim": null, "fig": null, "points": ["差异表达分析工具选择与实验设计密切相关，特别是生物学重复很少及基因表达水平较低的情况。", "limma在大多数实验中表现良好，且运行速度很快。", "DESeq和edgeR在显著性值排序上与limma表现相似，但对于错误发现率（FDR）的控制似乎过于宽松。", "SAMseq在FDR控制表现良好，但需要10个以上的生物学重复才能达到可接受的检测灵敏度。", "NOISeq和NOISeqBIO可以有效控制假阳性，同时牺牲了部分灵敏度。"], "check": {"q": "关于差异表达分析模型选择，下列说法正确的是？", "o": ["A. 最初使用高斯分布描述表达水平，但基因表达量不可能是负值，严格意义上并不符合正态分布", "B. 泊松分布适用于所有表达量范围，高表达基因方差与泊松分布方差完全一致", "C. 负二项分布不能用于RNA-seq差异表达分析", "D. 生物学重复越多，越适合直接采用非参数检验而不需要模型"], "a": "A", "e": "最初使用高斯分布描述表达水平，但表达量非负，严格意义上不符合正态分布；低表达基因方差符合泊松分布，高表达时实际方差远大于泊松分布方差，常用负二项分布等模型。"}, "cards": [{"front": "差异表达分析中常用的分布模型有哪些？", "back": "1. 高斯分布：最初使用高斯分布描述表达水平，然而基因表达量不可能是负值，严格意义上并不符合正态分布。2. 泊松分布：Marioni等研究发现RNA-seq技术重复条件下的测序方差与泊松分布方差相吻合。Simon等发现在生物学重复情况下，低表达基因方差符合泊松分布；随着表达量增加，方差逐渐偏离泊松分布。", "mnemonic": "", "useImg": false}, {"front": "常用差异表达分析工具limma的特点是什么？", "back": "limma在大多数实验中表现良好，且运行速度很快。", "mnemonic": "", "useImg": false}, {"front": "DESeq和edgeR在差异表达分析中的表现如何？", "back": "DESeq和edgeR在显著性值排序上与limma表现相似，但对于错误发现率（FDR）的控制似乎过于宽松。", "mnemonic": "", "useImg": false}, {"front": "SAMseq在差异表达分析中的表现如何？", "back": "SAMseq在FDR控制表现良好，但需要10个以上的生物学重复才能达到可接受的检测灵敏度。", "mnemonic": "", "useImg": false}]}, {"i": 11, "sec": "第四节 功能分析", "title": "常用差异表达分析工具比较", "notes": "差异表达分析工具选择与实验设计密切相关，特别是生物学重复很少及基因表达水平较低的情况。limma在大多数实验中表现良好，且运行速度很快。DESeq和edgeR在显著性值排序上与limma表现相似，但对于错误发现率（FDR）的控制似乎过于宽松。SAMseq在FDR控制表现良好，但需要10个以上的生物学重复才能达到可接受的检测灵敏度。NOISeq和NOISeqBIO可以有效控制假阳性，同时牺牲了部分灵敏度，但在不同处理条件生物学重复数不同的情况下表现良好。Cuffdiff和Cuffdiff2可以分析转录本水平的差异表达，但表现不如人意，反映了转录本水平的reads比对分配问题仍未很好解决，类似的异构体水平分析工具还有EBSeq等。上述工具大多只能进行成对比较，而Next maSigPro、DyNB、Ballgown和EBSeq-HMM等工具可以分析时间序列的RNA-seq数据。", "page": 113, "level": "理解", "img": "assets/img/ch06/p113.jpg", "anim": null, "fig": null, "points": ["差异表达分析工具选择与实验设计密切相关，特别是生物学重复很少及基因表达水平较低的情况。", "limma在大多数实验中表现良好，且运行速度很快。", "DESeq和edgeR在显著性值排序上与limma表现相似，但对于错误发现率（FDR）的控制似乎过于宽松。", "SAMseq在FDR控制表现良好，但需要10个以上的生物学重复才能达到可接受的检测灵敏度。", "NOISeq和NOISeqBIO可以有效控制假阳性，同时牺牲了部分灵敏度。"], "check": {"q": "关于常用差异表达分析工具比较，下列说法错误的是？", "o": ["A. limma在大多数实验中表现良好，且运行速度很快", "B. DESeq和edgeR在显著性值排序上与limma表现相似，但FDR控制似乎过于宽松", "C. SAMseq在FDR控制表现良好，但需要10个以上生物学重复才能达到可接受检测灵敏度", "D. NOISeq和NOISeqBIO灵敏度最高，且不牺牲任何假阳性控制"], "a": "D", "e": "NOISeq和NOISeqBIO可以有效控制假阳性，同时牺牲了部分灵敏度，并非灵敏度最高且不牺牲假阳性控制。"}, "cards": [{"front": "差异表达分析中常用的分布模型有哪些？", "back": "1. 高斯分布：最初使用高斯分布描述表达水平，然而基因表达量不可能是负值，严格意义上并不符合正态分布。2. 泊松分布：Marioni等研究发现RNA-seq技术重复条件下的测序方差与泊松分布方差相吻合。Simon等发现在生物学重复情况下，低表达基因方差符合泊松分布；随着表达量增加，方差逐渐偏离泊松分布。", "mnemonic": "", "useImg": false}, {"front": "常用差异表达分析工具limma的特点是什么？", "back": "limma在大多数实验中表现良好，且运行速度很快。", "mnemonic": "", "useImg": false}, {"front": "DESeq和edgeR在差异表达分析中的表现如何？", "back": "DESeq和edgeR在显著性值排序上与limma表现相似，但对于错误发现率（FDR）的控制似乎过于宽松。", "mnemonic": "", "useImg": false}, {"front": "SAMseq在差异表达分析中的表现如何？", "back": "SAMseq在FDR控制表现良好，但需要10个以上的生物学重复才能达到可接受的检测灵敏度。", "mnemonic": "", "useImg": false}]}, {"i": 12, "sec": "第四节 功能分析", "title": "聚类分析与共表达网络", "notes": "聚类分析是将表达模式相似的基因归为一类，以推断基因功能或调控关系。常用聚类方法包括层次聚类和K-means聚类。共表达网络构建基于基因表达相关性，将表达模式高度相关的基因连接成网络，进而识别模块和枢纽基因。加权基因共表达网络分析（WGCNA）是常用方法，通过计算基因间相关系数并加权，构建无尺度网络，识别共表达模块，并将模块与表型关联。GO和Pathway富集分析用于解释基因集的功能，GO富集包括生物学过程、分子功能和细胞组分三个本体，Pathway富集常用KEGG数据库。富集分析通过超几何检验或Fisher精确检验计算显著性，并进行多重检验校正。", "page": 114, "level": "理解", "img": "assets/img/ch06/p114.jpg", "anim": null, "fig": null, "points": ["聚类分析是将表达模式相似的基因归为一类，以推断基因功能或调控关系。", "常用聚类方法包括层次聚类和K-means聚类。", "共表达网络构建基于基因表达相关性，将表达模式高度相关的基因连接成网络，进而识别模块和枢纽基因。", "加权基因共表达网络分析（WGCNA）是常用方法，通过计算基因间相关系数并加权，构建无尺度网络，识别共表达模块，并将模块与表型关联。", "GO和Pathway富集分析用于解释基因集的功能，GO富集包括生物过程、分子功能和细胞组分。"], "check": {"q": "关于聚类分析与共表达网络，下列说法正确的是？", "o": ["A. 聚类分析是将表达模式相似的基因归为一类，以推断基因功能或调控关系", "B. WGCNA通过计算基因间相关系数并加权，构建随机网络而非无尺度网络", "C. GO富集只包括生物学过程一个本体", "D. 共表达网络不能用于识别模块和枢纽基因"], "a": "A", "e": "聚类分析将表达模式相似的基因归为一类；WGCNA构建无尺度网络并识别共表达模块；GO富集包括生物学过程、分子功能和细胞组分三个本体；共表达网络可用于识别模块和枢纽基因。"}, "cards": [{"front": "聚类分析的目的是什么？常用方法有哪些？", "back": "聚类分析是将表达模式相似的基因归为一类，以推断基因功能或调控关系。常用聚类方法包括层次聚类和K-means聚类。", "mnemonic": "", "useImg": false}, {"front": "加权基因共表达网络分析（WGCNA）是什么？", "back": "加权基因共表达网络分析（WGCNA）是常用方法，通过计算基因间相关系数并加权，构建无尺度网络，识别共表达模块，并将模块与表型关联。", "mnemonic": "", "useImg": false}]}, {"i": 13, "sec": "第四节 功能分析", "title": "可变剪切与基因融合分析", "notes": "RNA-seq可用于可变剪切分析，识别可变剪切位点和异构体表达水平。可变剪切类型包括外显子跳跃、内含子保留、可变5'剪接位点、可变3'剪接位点和互斥外显子等。常用工具如rMATS、Cufflinks、StringTie等可进行可变剪切分析。基因融合分析用于检测由染色体易位、缺失等引起的融合转录本，在肿瘤研究中尤为重要。常用工具如STAR-Fusion、FusionCatcher、SOAPfuse等。基因融合检测需注意假阳性控制，通常需结合多个证据如跨断点reads和成对reads。RNA-seq还可与全基因组测序、DNA表观修饰、ChIP-seq、ncRNA、蛋白质组和代谢组等多组学数据结合，构建转录调控网络、mRNA-ncRNA共表达网络、代谢网络等，揭示相关规律和机理。", "page": 122, "level": "了解", "img": "assets/img/ch06/p122.jpg", "anim": null, "fig": null, "points": ["本案例主要分析步骤采用Linux和Windows 7操作系统。", "官网下载VMware Workstation 12安装包和Ubuntu-16.04镜像文件，按照文档安装VMware，然后使用VMware安装虚拟机。", "虚拟机具体配置：64位，内存4GB，硬盘160GB；Windows 7配置：64位，内存16GB，硬盘1TB。", "测序数据来自NCBI GEO，检索号为GSE80568，测序平台为HiSeq。"], "check": {"q": "关于可变剪切与基因融合分析，下列说法错误的是？", "o": ["A. RNA-seq可用于识别可变剪切位点和异构体表达水平", "B. 可变剪切类型包括外显子跳跃、内含子保留、可变5'剪接位点、可变3'剪接位点和互斥外显子等", "C. rMATS、Cufflinks、StringTie等可用于可变剪切分析", "D. 基因融合分析在肿瘤研究中不重要，且不需要控制假阳性"], "a": "D", "e": "基因融合分析在肿瘤研究中尤为重要，常用STAR-Fusion、FusionCatcher、SOAPfuse等工具，并需注意假阳性控制。"}, "cards": [{"front": "可变剪切分析的类型有哪些？", "back": "可变剪切类型包括外显子跳跃、内含子保留、可变5'剪接位点、可变3'剪接位点和互斥外显子等。", "mnemonic": "", "useImg": false}, {"front": "常用可变剪切分析工具有哪些？", "back": "常用工具如rMATS、Cufflinks、StringTie等可进行可变剪切分析。", "mnemonic": "", "useImg": false}, {"front": "基因融合分析常用工具有哪些？", "back": "常用工具如STAR-Fusion、FusionCatcher、SOAPfuse等。", "mnemonic": "", "useImg": false}, {"front": "案例中使用的操作系统和虚拟机配置是什么？", "back": "本案例主要分析步骤采用Linux和Windows 7操作系统。虚拟机具体配置：64位，内存4GB，硬盘160GB；Windows 7配置：64位，内存16GB，硬盘1TB。", "mnemonic": "", "useImg": false}, {"front": "案例中测序数据的来源和检索号是什么？", "back": "测序数据来自NCBI GEO，检索号为GSE80568，测序平台为HiSeq。", "mnemonic": "", "useImg": false}]}, {"i": 14, "sec": "第五节 RNA-seq数据分析案例", "title": "案例系统配置与数据获取", "notes": "本案例主要分析步骤采用Linux和Windows 7操作系统。官网下载VMware Workstation 12安装包和Ubuntu-16.04镜像文件，按照文档安装VMware，然后使用VMware安装虚拟机。虚拟机具体配置：64位，内存4GB，硬盘160GB；Windows 7配置：64位，内存16GB，硬盘1TB。测序数据来自NCBI GEO，检索号为GSE80568，测序平台为HiSeq 2500，双端测序（PE）。数据集包括拟南芥幼苗的RNA-seq和ChIP-seq数据，原用于分析构建拟南芥抗渗透压胁迫下的转录调控网络。本实验只选取GSE80565中的两组数据，每组两个生物学重复。实验组为脱落酸（ABA）处理8h的拟南芥幼苗，对照组为乙醇（EtOH）处理8h的拟南芥幼苗。基因组数据来自拟南芥数据库TAIR，包括拟南芥染色体基因组序列和注释文件。将染色体序列合并成一个全基因组序列，使用Cufflinks自带的gffread工具将GFF注释文件转换为GTF格式。", "page": 122, "level": "了解", "img": "assets/img/ch06/p122.jpg", "anim": null, "fig": null, "points": ["本案例主要分析步骤采用Linux和Windows 7操作系统。", "官网下载VMware Workstation 12安装包和Ubuntu-16.04镜像文件，按照文档安装VMware，然后使用VMware安装虚拟机。", "虚拟机具体配置：64位，内存4GB，硬盘160GB；Windows 7配置：64位，内存16GB，硬盘1TB。", "测序数据来自NCBI GEO，检索号为GSE80568，测序平台为HiSeq。"], "check": {"q": "关于案例系统配置与数据获取，下列说法正确的是？", "o": ["A. 案例主要分析步骤采用Linux和Windows 7操作系统", "B. 虚拟机配置为32位，内存4GB，硬盘160GB", "C. Windows 7配置为64位，内存4GB，硬盘160GB", "D. 测序数据来自NCBI GEO，检索号为GSE80568，测序平台为HiSeq 2500，单端测序"], "a": "A", "e": "案例采用Linux和Windows 7；虚拟机为64位，内存4GB，硬盘160GB；Windows 7为64位，内存16GB，硬盘1TB；数据来自GSE80568，平台HiSeq 2500，双端测序。"}, "cards": [{"front": "可变剪切分析的类型有哪些？", "back": "可变剪切类型包括外显子跳跃、内含子保留、可变5'剪接位点、可变3'剪接位点和互斥外显子等。", "mnemonic": "", "useImg": false}, {"front": "常用可变剪切分析工具有哪些？", "back": "常用工具如rMATS、Cufflinks、StringTie等可进行可变剪切分析。", "mnemonic": "", "useImg": false}, {"front": "基因融合分析常用工具有哪些？", "back": "常用工具如STAR-Fusion、FusionCatcher、SOAPfuse等。", "mnemonic": "", "useImg": false}, {"front": "案例中使用的操作系统和虚拟机配置是什么？", "back": "本案例主要分析步骤采用Linux和Windows 7操作系统。虚拟机具体配置：64位，内存4GB，硬盘160GB；Windows 7配置：64位，内存16GB，硬盘1TB。", "mnemonic": "", "useImg": false}, {"front": "案例中测序数据的来源和检索号是什么？", "back": "测序数据来自NCBI GEO，检索号为GSE80568，测序平台为HiSeq。", "mnemonic": "", "useImg": false}]}, {"i": 15, "sec": "第五节 RNA-seq数据分析案例", "title": "案例数据预处理与质控", "notes": "使用fastq-dump工具从SRA文件中提取fastq序列文件，命令如：$ fastq-dump SRR3418005.sra &。对其余3个文件执行上述命令，产生的4个测序原始数据文件共计32.4GB。使用FastQC检测原始测序数据质量，命令如：$ fastqc -o ../fastqc_results -f fastq SRR3418005.fastq SRR3418006.fastq SRR3418019.fastq SRR3418020.fastq &。参数说明：-o指定输出目录，-f指定输入格式。根据FastQC结果，关键的Per base sequence quality评估为正常，而Per base sequence content结果显示约前12位的碱基核酸比例失常。若对测序质量要求较高，可以使用FastX_Toolkit进行质量控制。使用fastx_trimmer截去reads前12位碱基，命令如：$ fastx_trimmer -Q 33 -f 12 -i SRR3418005.fastq -o fastx_results/SRR3418005_trimmed.fastq &。参数说明：-Q为Illumina编码转换，-f为截取起始位置，-i输入文件，-o输出文件。使用fastq_quality_filter过滤低质量reads，命令如：$ fastq_quality_filter -Q 33 -q 20 -p 80 -i SRR3418005_trimmed.fastq -o SRR3418005_filtered.fastq &。参数说明：-Q同上，-q保留结果所需达到的最低得分，-p每个reads中达到-q得分的最小百分数。对处理后的序列再进行质量评估，结果显示Per base sequence content等指标提升，而Sequence duplication levels和Kmer Content仍然未达标，但已经可以用于RNA-seq分析。", "page": 123, "level": "掌握", "img": "assets/img/ch06/p123.jpg", "anim": null, "fig": null, "points": ["使用fastq-dump工具从SRA文件中提取fastq序列文件，命令如：$ fastq-dump SRR3418005.sra &。", "对其余3个文件执行上述命令，产生的4个测序原始数据文件共计32.4GB。", "使用FastQC检测原始测序数据质量，命令如：$ fastqc -o ../fastqc_results -f fastq SRR3418005.fastq SRR3418006.fastq S。"], "check": {"q": "关于案例数据预处理与质控，下列说法错误的是？", "o": ["A. 使用fastq-dump工具从SRA文件中提取fastq序列文件", "B. 命令$ fastq-dump SRR3418005.sra & 可用于提取fastq序列文件", "C. 使用FastQC检测原始测序数据质量", "D. 4个测序原始数据文件共计约3.24GB"], "a": "D", "e": "案例中4个测序原始数据文件共计32.4GB，而不是3.24GB；其余关于fastq-dump和FastQC的描述正确。"}, "cards": [{"front": "RNA-seq数据预处理包括哪些步骤？", "back": "RNA-seq数据预处理包括提取fastq文件、质量评估和质量控制。", "mnemonic": "", "useImg": false}, {"front": "如何从SRA文件中提取fastq序列文件？", "back": "使用fastq-dump工具从SRA文件中提取fastq序列文件。", "mnemonic": "", "useImg": false}, {"front": "使用什么工具检测原始测序数据质量？关键指标有哪些？", "back": "使用FastQC检测原始测序数据质量，关键指标包括Per base sequence quality、Per base sequence content等。", "mnemonic": "", "useImg": false}, {"front": "案例中如何使用fastq-dump提取fastq文件？", "back": "使用fastq-dump工具从SRA文件中提取fastq序列文件，命令如：$ fastq-dump SRR3418005.sra &。对其余3个文件执行上述命令，产生的4个测序原始数据文件共计32.4GB。", "mnemonic": "", "useImg": false}, {"front": "案例中如何使用FastQC检测原始测序数据质量？", "back": "使用FastQC检测原始测序数据质量，命令如：$ fastqc -o ../fastqc_results -f fastq SRR3418005.fastq SRR3418006.fastq S。", "mnemonic": "", "useImg": false}]}], "mcq": [{"id": "ch06_mcq_1", "mod": "第六章 转录组学", "modI": 0, "q": "关于转录组学，以下描述正确的是？", "o": ["A. 转录组学的研究对象是基因组DNA", "B. 转录组学一词最早在20世纪90年代提出", "C. 转录组仅指mRNA", "D. 转录组学从蛋白质水平研究基因表达"], "a": "B", "e": "转录组学一词最早在20世纪90年代提出，研究对象是全基因组尺度下所有转录本。广义上转录组包括mRNA、rRNA、tRNA、ncRNA等，但有时特指mRNA。转录组学从RNA水平研究基因表达。", "kp": "ch06_s0_0"}, {"id": "ch06_mcq_2", "mod": "第六章 转录组学", "modI": 0, "q": "RNA-seq与基因芯片相比，以下哪项不是RNA-seq的优势？", "o": ["A. 不依赖于参考基因组", "B. 可以直接测定转录本序列和含量", "C. 通量极高", "D. 荧光信号动态检测范围有限"], "a": "D", "e": "荧光信号动态检测范围有限是基因芯片的缺陷，不是RNA-seq的优势。RNA-seq的优势包括不依赖参考基因组、直接测定转录本序列和含量、通量极高、成本日益降低等。", "kp": "ch06_s0_2"}, {"id": "ch06_mcq_3", "mod": "第六章 转录组学", "modI": 0, "q": "RNA-seq试验设计中，对于有参考基因组且不进行可变剪切或新转录本分析的情况，每个样本最少需要多少有效reads？", "o": ["A. 1M", "B. 5M", "C. 10M", "D. 30M"], "a": "B", "e": "根据ENCODE推荐，有参考基因组且不进行可变剪切或新转录本分析时，每个样本最少只需要5M的有效reads。small RNA一般需要30M以上的有效匹配reads。", "kp": "ch06_s0_3"}, {"id": "ch06_mcq_4", "mod": "第六章 转录组学", "modI": 0, "q": "关于链特异性文库，以下描述正确的是？", "o": ["A. 无法区分转录本来源", "B. 保留了转录本的方向信息", "C. 价格比非链特异性文库低", "D. 不利于可变剪切鉴别"], "a": "B", "e": "链特异性文库在建库时保留了转录本的方向信息，用以区分转录本来源，避免互补链干扰。相较于非链特异性文库，基因表达定量和可变剪切鉴别更准确，但价格更高。", "kp": "ch06_s0_5"}, {"id": "ch06_mcq_5", "mod": "第六章 转录组学", "modI": 0, "q": "FASTQ文件中，一个read通常由几行组成？", "o": ["A. 2行", "B. 3行", "C. 4行", "D. 5行"], "a": "C", "e": "FASTQ文件中一个read通常由四行组成：第一行以@开头，为序列标识符及描述信息；第二行为read的序列信息；第三行以+开头，可再次添加序列描述信息（可选）；第四行为质量得分信息，长度必须与第二行相同。", "kp": "ch06_s0_6"}, {"id": "ch06_mcq_6", "mod": "第六章 转录组学", "modI": 0, "q": "在差异表达分析中，负二项分布相比泊松分布的优势是什么？", "o": ["A. 更简单", "B. 可以拟合基因表达方差远大于均值的情况", "C. 不需要生物学重复", "D. 计算速度更快"], "a": "B", "e": "负二项分布的方差可以通过调整散度因子α的值来调节模型的离散度，使其符合实际情况中基因表达方差远大于均值的情况。泊松分布模型可能严重低估个体差异带来的误差。", "kp": "ch06_s0_10"}, {"id": "ch06_mcq_7", "mod": "第六章 转录组学", "modI": 0, "q": "以下哪个工具采用β负二项分布进行差异表达分析？", "o": ["A. DESeq", "B. edgeR", "C. Cuffdiff", "D. limma"], "a": "C", "e": "Cuffdiff采用β负二项分布，该分布可以拟合比对过程中的多重比对reads分配误差，与负二项分布结合而成。DESeq和edgeR采用负二项分布，limma采用线性模型。", "kp": "ch06_s0_10"}, {"id": "ch06_mcq_8", "mod": "第六章 转录组学", "modI": 0, "q": "Trinity软件中，负责将contigs聚类并构建de Bruijn图的模块是？", "o": ["A. Inchworm", "B. Chrysalis", "C. Butterfly", "D. Bowtie"], "a": "B", "e": "Trinity包含Inchworm、Chrysalis和Butterfly三个模块。Inchworm将reads切割为k-mers并延伸组装成contigs；Chrysalis将contigs聚类并构建de Bruijn图；Butterfly拆分de Bruijn图为线性序列，得到全长转录本。", "kp": "ch06_s0_8"}, {"id": "ch06_mcq_9", "mod": "第六章 转录组学", "modI": 0, "q": "在RNA-seq数据分析中，用于检测原始测序数据质量的工具是？", "o": ["A. fastq-dump", "B. FastQC", "C. fastx_trimmer", "D. fastq_quality_filter"], "a": "B", "e": "FastQC用于检测原始测序数据质量。fastq-dump用于从SRA文件中提取fastq序列文件；fastx_trimmer用于截去reads前几位碱基；fastq_quality_filter用于过滤低质量reads。", "kp": "ch06_s0_7"}, {"id": "ch06_mcq_10", "mod": "第六章 转录组学", "modI": 0, "q": "关于RNA-seq与多组学结合分析，以下描述错误的是？", "o": ["A. 结合全基因组测序数据可以探测SNP和eQTL", "B. 结合DNA表观修饰数据可以探究表观修饰对差异表达基因的影响", "C. RNA-seq与蛋白质组学数据相关性很高，可直接整合", "D. 结合ChIP-seq可以研究转录因子调节基因表达的动态规律"], "a": "C", "e": "RNA-seq与蛋白质组学数据的相关性较低，具体应用需要慎重考虑。其他选项描述正确：结合全基因组测序可探测SNP和eQTL；结合DNA表观修饰数据可探究表观修饰对差异表达基因的影响；结合ChIP-seq可研究转录因子调节基因表达的动态规律。", "kp": "ch06_s0_2"}], "judge": [{"id": "ch06_judge_1", "modI": 0, "q": "中心法则由Crick于1958年提出，描述遗传信息从DNA经RNA传递至蛋白质的流向。", "a": "对", "e": "讲义明确指出中心法则由Crick于1958年提出，描述DNA经RNA到蛋白质的信息流。", "kp": "ch06_s0_0"}, {"id": "ch06_judge_2", "modI": 0, "q": "转录组学在20世纪90年代提出，研究对象是全基因组尺度下所有转录本。", "a": "对", "e": "转录组学在20世纪90年代提出，研究对象为全基因组尺度下所有转录本，即转录组。", "kp": "ch06_s0_0"}, {"id": "ch06_judge_3", "modI": 0, "q": "RNA-seq必须依赖参考基因组才能直接测定转录本序列和含量。", "a": "错", "e": "RNA-seq不依赖参考基因组，可直接测定转录本序列和含量；无参考基因组时也可进行从头组装。", "kp": "ch06_s0_2"}, {"id": "ch06_judge_4", "modI": 0, "q": "基因芯片技术存在交叉杂交背景噪声、低表达丰度基因检测困难、荧光信号动态检测范围有限等缺陷。", "a": "对", "e": "讲义明确列出基因芯片的这些缺陷。", "kp": "ch06_s0_1"}, {"id": "ch06_judge_5", "modI": 0, "q": "RNA-seq实验设计时，生物学重复一般建议3~5个，假阳性控制要求高时可适当增加。", "a": "对", "e": "讲义指出没有重复难以排除随机误差，过多重复增加成本，一般3~5个，假阳性控制要求高时可适当增加。", "kp": "ch06_s0_3"}, {"id": "ch06_judge_6", "modI": 0, "q": "FASTQ文件中第四行为质量得分信息，其长度可以与第二行序列长度不同。", "a": "错", "e": "FASTQ第四行质量得分信息与第二行序列相对应，长度必须与第二行相同。", "kp": "ch06_s0_6"}, {"id": "ch06_judge_7", "modI": 0, "q": "使用fastx_trimmer时，参数-Q 33为Illumina编码转换。", "a": "对", "e": "讲义中fastx_trimmer参数说明指出-Q 33为Illumina编码转换。", "kp": "ch06_s0_7"}, {"id": "ch06_judge_8", "modI": 0, "q": "差异表达分析中，无重复样本时差异表达分析结果可靠性下降。", "a": "对", "e": "讲义指出计算组内差异需要生物学重复，无重复样本时差异表达分析结果可靠性下降。", "kp": "ch06_s0_9"}, {"id": "ch06_judge_9", "modI": 0, "q": "DESeq和edgeR都采用高斯分布描述reads频数分布。", "a": "错", "e": "DESeq和edgeR都采用负二项分布描述reads频数分布，而不是高斯分布。", "kp": "ch06_s0_10"}, {"id": "ch06_judge_10", "modI": 0, "q": "WGCNA是加权基因共表达网络分析，可通过计算基因间相关系数并加权，构建无尺度网络，识别共表达模块。", "a": "对", "e": "讲义指出WGCNA是常用共表达网络方法，通过相关系数加权构建无尺度网络，识别共表达模块并与表型关联。", "kp": "ch06_s0_12"}], "fill": [{"id": "ch06_fill_1", "modI": 0, "q": "中心法则由Crick于1958年提出，描述遗传信息从DNA经________传递至蛋白质的流向。", "a": "RNA", "kp": "ch06_s0_0"}, {"id": "ch06_fill_2", "modI": 0, "q": "转录组学在20世纪90年代提出，研究对象是全基因组尺度下所有________，即转录组。", "a": "转录本", "kp": "ch06_s0_0"}, {"id": "ch06_fill_3", "modI": 0, "q": "RNA-seq与基因芯片相比，通量方面基因芯片较低，RNA-seq________。", "a": "高", "kp": "ch06_s0_2"}, {"id": "ch06_fill_4", "modI": 0, "q": "RNA-seq实验设计时，生物学重复一般建议________个，假阳性控制要求高时可适当增加。", "a": "3~5", "kp": "ch06_s0_3"}, {"id": "ch06_fill_5", "modI": 0, "q": "有参考基因组且不进行可变剪切或新转录本分析时，每个样本最少需要________有效reads（ENCODE推荐）。", "a": "5M", "kp": "ch06_s0_3"}, {"id": "ch06_fill_6", "modI": 0, "q": "FASTQ文件中一个read通常由四行组成：第一行以@开头，第二行为read的序列信息，第三行以________开头，第四行为质量得分信息。", "a": "+", "kp": "ch06_s0_6"}, {"id": "ch06_fill_7", "modI": 0, "q": "使用fastx_trimmer截去reads前12位碱基时，参数________为Illumina编码转换。", "a": "-Q 33", "kp": "ch06_s0_7"}, {"id": "ch06_fill_8", "modI": 0, "q": "差异表达分析中，DESeq和edgeR都采用________分布描述reads频数分布。", "a": "负二项", "kp": "ch06_s0_10"}], "short": [{"id": "ch06_short_1", "modI": 0, "q": "简述RNA-seq与基因芯片相比的主要优势。", "a": "1. 不依赖参考基因组，可直接测定转录本序列和含量；2. 通量极高；3. 成本日益降低，趋向大众化；4. 动态范围依赖测序深度，可更好覆盖低丰度转录本；5. 可发现新转录本、可变剪切和基因融合等。", "kp": "ch06_s0_2"}, {"id": "ch06_short_2", "modI": 0, "q": "简述RNA-seq实验设计需考虑的主要问题。", "a": "1. 生物学重复：一般3~5个，假阳性控制要求高时可增加；2. 样本提取：控制干扰变量，注意提取时间和组织细胞控制，提取后及时冷冻保存；3. 测序深度：有参考基因组且不分析可变剪切或新转录本时每样本最少5M有效reads，鉴定新转录本或无参考基因组时增加，small RNA一般需30M以上有效匹配reads；4. 文库构建：链特异性文库保留方向信息，定量和可变剪切鉴别更准确但价格更高；5. 测序策略：单末端测序更快、价格低，一般足够定量；双末端测序有利于基因注释和转录本异构体发现。", "kp": "ch06_s0_3"}, {"id": "ch06_short_3", "modI": 0, "q": "简述RNA-seq文库制备的主要流程。", "a": "1. 选择感兴趣样本提取RNA；2. 采用PolyA富集或rRNA移除策略分离纯化RNA；3. 随机打碎成短片段并反转录为cDNA；4. 选择合适长度片段添加接头构建文库；5. 扩增并测序。cDNA文库制备关键步骤包括总RNA提取、RNA分离纯化、cDNA合成。", "kp": "ch06_s0_5"}, {"id": "ch06_short_4", "modI": 0, "q": "简述差异表达分析中差异的来源及处理效应检验的基本思路。", "a": "1. 不同实验处理引起的差异称为处理差异；2. 同一实验条件下不同样本之间由于个体差异、技术误差等存在差异，称为组内差异；3. 直接比较组间差异时包括组内差异和处理差异；4. 最终检验处理效应显著性时，应由组间差异减去组内差异；5. 计算组内差异需要生物学重复，无重复样本时差异表达分析结果可靠性下降。", "kp": "ch06_s0_9"}, {"id": "ch06_short_5", "modI": 0, "q": "简述常用差异表达分析模型及其适用性。", "a": "1. 高斯分布：最初用于描述表达水平，但基因表达量不可能是负值，严格意义上不符合正态分布；2. 泊松分布：技术重复条件下测序方差与泊松分布方差吻合，低表达基因方差符合泊松分布，但表达量升高后实际方差远大于泊松分布方差；3. 负二项分布：可调整散度因子α调节模型离散度，符合基因表达方差远大于均值的情况，DESeq和edgeR采用；4. β负二项分布：可拟合多重比对reads分配误差，与负二项分布结合，Cuffdiff采用。", "kp": "ch06_s0_11"}], "calc": [{"id": "ch06_calc_1", "modI": 0, "q": "论述RNA-seq数据分析中，有参考基因组和无参考基因组两种策略的主要流程差异，并说明各自常用工具。", "a": "有参考基因组时，RNA-seq核心分析通常包括序列比对和表达定量。可使用Bowtie、HISAT2、STAR等将reads比对到参考基因组或转录组；随后利用HTSeq-count或RSEM等进行reads计数并估算表达量；还可进行可变剪切、基因融合和差异表达分析。无参考基因组时，需先进行从头组装，如Trinity软件包含Inchworm、Chrysalis和Butterfly三个模块：Inchworm将reads切割为k-mers并延伸组装成contigs；Chrysalis将contigs聚类并构建de Bruijn图；Butterfly拆分de Bruijn图并依据reads和成对reads寻找最佳路径，得到具有可变剪切的全长转录本。组装完成后需评估质量，包括组装完整性、准确性及冗余度；再将reads通过Bowtie重新比对到组装转录本上，利用HTSeq-count或RSEM等计数估算表达量，并可通过Blast2GO等进行功能注释。", "steps": "1. 有参考基因组：比对到参考基因组/转录组；2. 常用比对工具：Bowtie、HISAT2、STAR；3. 定量工具：HTSeq-count、RSEM；4. 无参考基因组：从头组装；5. Trinity三模块：Inchworm、Chrysalis、Butterfly；6. 组装质量评估：完整性、准确性、冗余度；7. 重新比对与定量；8. 功能注释：Blast2GO等。", "kp": "ch06_s0_2"}, {"id": "ch06_calc_2", "modI": 0, "q": "结合案例，论述RNA-seq数据预处理与质控的主要步骤、常用命令参数及质控结果解读。", "a": "案例中RNA-seq数据预处理包括提取fastq文件、质量评估和质量控制。首先使用fastq-dump工具从SRA文件中提取fastq序列文件，如$ fastq-dump SRR3418005.sra &，对其余文件执行相同命令。然后使用FastQC检测原始测序数据质量，如$ fastqc -o ../fastqc_results -f fastq SRR3418005.fastq SRR3418006.fastq SRR3418019.fastq SRR3418020.fastq &，其中-o指定输出目录，-f指定输入格式。根据FastQC结果，Per base sequence quality评估为正常，而Per base sequence content显示约前12位碱基核酸比例失常。若测序质量要求较高，可使用FastX_Toolkit进行质量控制：使用fastx_trimmer截去reads前12位碱基，如$ fastx_trimmer -Q 33 -f 12 -i SRR3418005.fastq -o fastx_results/SRR3418005_trimmed.fastq &，其中-Q为Illumina编码转换，-f为截取起始位置，-i输入文件，-o输出文件；使用fastq_quality_filter过滤低质量reads，如$ fastq_quality_filter -Q 33 -q 20 -p 80 -i SRR3418005_trimmed.fastq -o SRR3418005_filtered.fastq &，其中-q为保留结果所需达到的最低得分，-p为每个reads中达到-q得分的最小百分数。处理后再次质量评估，Per base sequence content等指标提升，Sequence duplication levels和Kmer Content可能仍未达标，但已可用于RNA-seq分析。", "steps": "1. fastq-dump提取fastq；2. FastQC质量评估；3. 关键指标：Per base sequence quality、Per base sequence content；4. fastx_trimmer截去前12位碱基；5. 参数：-Q 33、-f、-i、-o；6. fastq_quality_filter过滤低质量reads；7. 参数：-q、-p；8. 处理后复评；9. 部分指标提升，部分未达标但可用于分析。", "kp": "ch06_s0_15"}], "term": [{"id": "ch06_term_1", "modI": 0, "term": "Central Dogma", "def": "由Crick于1958年提出，描述遗传信息从DNA经RNA传递至蛋白质的基本流向；对应三个组学层次：基因组学、转录组学和蛋白质组学。", "kp": "ch06_s0_15"}, {"id": "ch06_term_2", "modI": 0, "term": "Transcriptomics", "def": "20世纪90年代提出，在转录组水平研究基因表达；研究对象是全基因组尺度下所有转录本（transcriptome）。广义包括mRNA、rRNA、tRNA、ncRNA等，狭义常特指mRNA。", "kp": "ch06_s0_0"}, {"id": "ch06_term_3", "modI": 0, "term": "Transcriptome", "def": "细胞或组织中所有RNA分子的总和；包括mRNA、rRNA、tRNA、ncRNA等；本章无特殊说明时专指mRNA。", "kp": "ch06_s0_0"}, {"id": "ch06_term_4", "modI": 0, "term": "RNA-seq", "def": "基于第二代测序的转录组测序技术；不依赖参考基因组即可直接测定转录本序列和含量；通量高、成本日益降低；自2008年Nagalakshmi等用于酵母转录组研究后广泛应用。", "kp": "ch06_s0_2"}, {"id": "ch06_term_5", "modI": 0, "term": "Microarray", "def": "基于杂交的基因芯片技术；将荧光标记cDNA制成微阵列探针；通量较高、价格相对较低；但需参考转录组信息，存在交叉杂交背景噪声、低表达丰度基因检测困难、荧光信号动态范围有限等缺陷。", "kp": "ch06_s0_0"}, {"id": "ch06_term_6", "modI": 0, "term": "FASTQ", "def": "存储生物序列及其测序质量得分的文本格式；最初由Wellcome Trust Sanger研究所开发，用于捆绑FASTA序列及质量数据；现为高通量测序仪输出实际标准。每个read通常四行：@标识行、序列行、+行、质量得分行；质量行长度必须与序列行相同。", "kp": "ch06_s0_6"}, {"id": "ch06_term_7", "modI": 0, "term": "FastQC", "def": "用于检测原始测序数据质量的工具；关键指标包括Per base sequence quality、Per base sequence content等；用于RNA-seq数据预处理中的质量评估。", "kp": "ch06_s0_7"}, {"id": "ch06_term_8", "modI": 0, "term": "FastX_Toolkit", "def": "用于测序数据质量控制的工具集；常用fastx_trimmer截去reads前12位碱基，fastq_quality_filter过滤低质量reads；参数-Q 33用于Illumina编码转换。", "kp": "ch06_s0_7"}, {"id": "ch06_term_9", "modI": 0, "term": "Bowtie", "def": "短序列比对工具；有参考基因组时可将RNA-seq reads比对到参考基因组或转录组；组装后也可将reads重新比对到组装转录本上用于表达定量。", "kp": "ch06_s0_8"}, {"id": "ch06_term_10", "modI": 0, "term": "HISAT2", "def": "RNA-seq有参考基因组分析中的比对工具；可将reads比对到参考基因组或转录组，用于后续表达定量和可变剪切分析。", "kp": "ch06_s0_8"}, {"id": "ch06_term_11", "modI": 0, "term": "STAR", "def": "RNA-seq有参考基因组分析中的比对工具；可将reads比对到参考基因组或转录组；也常用于基因融合分析相关流程。", "kp": "ch06_s0_6"}, {"id": "ch06_term_12", "modI": 0, "term": "Trinity", "def": "无参考基因组时进行从头组装的软件；包含Inchworm、Chrysalis和Butterfly三个模块。Inchworm将reads切割为k-mers并延伸组装成contigs；Chrysalis聚类contigs并构建de Bruijn图；Butterfly拆分de Bruijn图并寻找最佳路径，得到具有可变剪切的全长转录本。", "kp": "ch06_s0_8"}]}], "mcq": [{"id": "ch06_mcq_1", "mod": "第六章 转录组学", "modI": 0, "q": "关于转录组学，以下描述正确的是？", "o": ["A. 转录组学的研究对象是基因组DNA", "B. 转录组学一词最早在20世纪90年代提出", "C. 转录组仅指mRNA", "D. 转录组学从蛋白质水平研究基因表达"], "a": "B", "e": "转录组学一词最早在20世纪90年代提出，研究对象是全基因组尺度下所有转录本。广义上转录组包括mRNA、rRNA、tRNA、ncRNA等，但有时特指mRNA。转录组学从RNA水平研究基因表达。", "kp": "ch06_s0_0"}, {"id": "ch06_mcq_2", "mod": "第六章 转录组学", "modI": 0, "q": "RNA-seq与基因芯片相比，以下哪项不是RNA-seq的优势？", "o": ["A. 不依赖于参考基因组", "B. 可以直接测定转录本序列和含量", "C. 通量极高", "D. 荧光信号动态检测范围有限"], "a": "D", "e": "荧光信号动态检测范围有限是基因芯片的缺陷，不是RNA-seq的优势。RNA-seq的优势包括不依赖参考基因组、直接测定转录本序列和含量、通量极高、成本日益降低等。", "kp": "ch06_s0_2"}, {"id": "ch06_mcq_3", "mod": "第六章 转录组学", "modI": 0, "q": "RNA-seq试验设计中，对于有参考基因组且不进行可变剪切或新转录本分析的情况，每个样本最少需要多少有效reads？", "o": ["A. 1M", "B. 5M", "C. 10M", "D. 30M"], "a": "B", "e": "根据ENCODE推荐，有参考基因组且不进行可变剪切或新转录本分析时，每个样本最少只需要5M的有效reads。small RNA一般需要30M以上的有效匹配reads。", "kp": "ch06_s0_3"}, {"id": "ch06_mcq_4", "mod": "第六章 转录组学", "modI": 0, "q": "关于链特异性文库，以下描述正确的是？", "o": ["A. 无法区分转录本来源", "B. 保留了转录本的方向信息", "C. 价格比非链特异性文库低", "D. 不利于可变剪切鉴别"], "a": "B", "e": "链特异性文库在建库时保留了转录本的方向信息，用以区分转录本来源，避免互补链干扰。相较于非链特异性文库，基因表达定量和可变剪切鉴别更准确，但价格更高。", "kp": "ch06_s0_5"}, {"id": "ch06_mcq_5", "mod": "第六章 转录组学", "modI": 0, "q": "FASTQ文件中，一个read通常由几行组成？", "o": ["A. 2行", "B. 3行", "C. 4行", "D. 5行"], "a": "C", "e": "FASTQ文件中一个read通常由四行组成：第一行以@开头，为序列标识符及描述信息；第二行为read的序列信息；第三行以+开头，可再次添加序列描述信息（可选）；第四行为质量得分信息，长度必须与第二行相同。", "kp": "ch06_s0_6"}, {"id": "ch06_mcq_6", "mod": "第六章 转录组学", "modI": 0, "q": "在差异表达分析中，负二项分布相比泊松分布的优势是什么？", "o": ["A. 更简单", "B. 可以拟合基因表达方差远大于均值的情况", "C. 不需要生物学重复", "D. 计算速度更快"], "a": "B", "e": "负二项分布的方差可以通过调整散度因子α的值来调节模型的离散度，使其符合实际情况中基因表达方差远大于均值的情况。泊松分布模型可能严重低估个体差异带来的误差。", "kp": "ch06_s0_10"}, {"id": "ch06_mcq_7", "mod": "第六章 转录组学", "modI": 0, "q": "以下哪个工具采用β负二项分布进行差异表达分析？", "o": ["A. DESeq", "B. edgeR", "C. Cuffdiff", "D. limma"], "a": "C", "e": "Cuffdiff采用β负二项分布，该分布可以拟合比对过程中的多重比对reads分配误差，与负二项分布结合而成。DESeq和edgeR采用负二项分布，limma采用线性模型。", "kp": "ch06_s0_10"}, {"id": "ch06_mcq_8", "mod": "第六章 转录组学", "modI": 0, "q": "Trinity软件中，负责将contigs聚类并构建de Bruijn图的模块是？", "o": ["A. Inchworm", "B. Chrysalis", "C. Butterfly", "D. Bowtie"], "a": "B", "e": "Trinity包含Inchworm、Chrysalis和Butterfly三个模块。Inchworm将reads切割为k-mers并延伸组装成contigs；Chrysalis将contigs聚类并构建de Bruijn图；Butterfly拆分de Bruijn图为线性序列，得到全长转录本。", "kp": "ch06_s0_8"}, {"id": "ch06_mcq_9", "mod": "第六章 转录组学", "modI": 0, "q": "在RNA-seq数据分析中，用于检测原始测序数据质量的工具是？", "o": ["A. fastq-dump", "B. FastQC", "C. fastx_trimmer", "D. fastq_quality_filter"], "a": "B", "e": "FastQC用于检测原始测序数据质量。fastq-dump用于从SRA文件中提取fastq序列文件；fastx_trimmer用于截去reads前几位碱基；fastq_quality_filter用于过滤低质量reads。", "kp": "ch06_s0_7"}, {"id": "ch06_mcq_10", "mod": "第六章 转录组学", "modI": 0, "q": "关于RNA-seq与多组学结合分析，以下描述错误的是？", "o": ["A. 结合全基因组测序数据可以探测SNP和eQTL", "B. 结合DNA表观修饰数据可以探究表观修饰对差异表达基因的影响", "C. RNA-seq与蛋白质组学数据相关性很高，可直接整合", "D. 结合ChIP-seq可以研究转录因子调节基因表达的动态规律"], "a": "C", "e": "RNA-seq与蛋白质组学数据的相关性较低，具体应用需要慎重考虑。其他选项描述正确：结合全基因组测序可探测SNP和eQTL；结合DNA表观修饰数据可探究表观修饰对差异表达基因的影响；结合ChIP-seq可研究转录因子调节基因表达的动态规律。", "kp": "ch06_s0_2"}], "judge": [{"id": "ch06_judge_1", "modI": 0, "q": "中心法则由Crick于1958年提出，描述遗传信息从DNA经RNA传递至蛋白质的流向。", "a": "对", "e": "讲义明确指出中心法则由Crick于1958年提出，描述DNA经RNA到蛋白质的信息流。", "kp": "ch06_s0_0"}, {"id": "ch06_judge_2", "modI": 0, "q": "转录组学在20世纪90年代提出，研究对象是全基因组尺度下所有转录本。", "a": "对", "e": "转录组学在20世纪90年代提出，研究对象为全基因组尺度下所有转录本，即转录组。", "kp": "ch06_s0_0"}, {"id": "ch06_judge_3", "modI": 0, "q": "RNA-seq必须依赖参考基因组才能直接测定转录本序列和含量。", "a": "错", "e": "RNA-seq不依赖参考基因组，可直接测定转录本序列和含量；无参考基因组时也可进行从头组装。", "kp": "ch06_s0_2"}, {"id": "ch06_judge_4", "modI": 0, "q": "基因芯片技术存在交叉杂交背景噪声、低表达丰度基因检测困难、荧光信号动态检测范围有限等缺陷。", "a": "对", "e": "讲义明确列出基因芯片的这些缺陷。", "kp": "ch06_s0_1"}, {"id": "ch06_judge_5", "modI": 0, "q": "RNA-seq实验设计时，生物学重复一般建议3~5个，假阳性控制要求高时可适当增加。", "a": "对", "e": "讲义指出没有重复难以排除随机误差，过多重复增加成本，一般3~5个，假阳性控制要求高时可适当增加。", "kp": "ch06_s0_3"}, {"id": "ch06_judge_6", "modI": 0, "q": "FASTQ文件中第四行为质量得分信息，其长度可以与第二行序列长度不同。", "a": "错", "e": "FASTQ第四行质量得分信息与第二行序列相对应，长度必须与第二行相同。", "kp": "ch06_s0_6"}, {"id": "ch06_judge_7", "modI": 0, "q": "使用fastx_trimmer时，参数-Q 33为Illumina编码转换。", "a": "对", "e": "讲义中fastx_trimmer参数说明指出-Q 33为Illumina编码转换。", "kp": "ch06_s0_7"}, {"id": "ch06_judge_8", "modI": 0, "q": "差异表达分析中，无重复样本时差异表达分析结果可靠性下降。", "a": "对", "e": "讲义指出计算组内差异需要生物学重复，无重复样本时差异表达分析结果可靠性下降。", "kp": "ch06_s0_9"}, {"id": "ch06_judge_9", "modI": 0, "q": "DESeq和edgeR都采用高斯分布描述reads频数分布。", "a": "错", "e": "DESeq和edgeR都采用负二项分布描述reads频数分布，而不是高斯分布。", "kp": "ch06_s0_10"}, {"id": "ch06_judge_10", "modI": 0, "q": "WGCNA是加权基因共表达网络分析，可通过计算基因间相关系数并加权，构建无尺度网络，识别共表达模块。", "a": "对", "e": "讲义指出WGCNA是常用共表达网络方法，通过相关系数加权构建无尺度网络，识别共表达模块并与表型关联。", "kp": "ch06_s0_12"}], "fill": [{"id": "ch06_fill_1", "modI": 0, "q": "中心法则由Crick于1958年提出，描述遗传信息从DNA经________传递至蛋白质的流向。", "a": "RNA", "kp": "ch06_s0_0"}, {"id": "ch06_fill_2", "modI": 0, "q": "转录组学在20世纪90年代提出，研究对象是全基因组尺度下所有________，即转录组。", "a": "转录本", "kp": "ch06_s0_0"}, {"id": "ch06_fill_3", "modI": 0, "q": "RNA-seq与基因芯片相比，通量方面基因芯片较低，RNA-seq________。", "a": "高", "kp": "ch06_s0_2"}, {"id": "ch06_fill_4", "modI": 0, "q": "RNA-seq实验设计时，生物学重复一般建议________个，假阳性控制要求高时可适当增加。", "a": "3~5", "kp": "ch06_s0_3"}, {"id": "ch06_fill_5", "modI": 0, "q": "有参考基因组且不进行可变剪切或新转录本分析时，每个样本最少需要________有效reads（ENCODE推荐）。", "a": "5M", "kp": "ch06_s0_3"}, {"id": "ch06_fill_6", "modI": 0, "q": "FASTQ文件中一个read通常由四行组成：第一行以@开头，第二行为read的序列信息，第三行以________开头，第四行为质量得分信息。", "a": "+", "kp": "ch06_s0_6"}, {"id": "ch06_fill_7", "modI": 0, "q": "使用fastx_trimmer截去reads前12位碱基时，参数________为Illumina编码转换。", "a": "-Q 33", "kp": "ch06_s0_7"}, {"id": "ch06_fill_8", "modI": 0, "q": "差异表达分析中，DESeq和edgeR都采用________分布描述reads频数分布。", "a": "负二项", "kp": "ch06_s0_10"}], "short": [{"id": "ch06_short_1", "modI": 0, "q": "简述RNA-seq与基因芯片相比的主要优势。", "a": "1. 不依赖参考基因组，可直接测定转录本序列和含量；2. 通量极高；3. 成本日益降低，趋向大众化；4. 动态范围依赖测序深度，可更好覆盖低丰度转录本；5. 可发现新转录本、可变剪切和基因融合等。", "kp": "ch06_s0_2"}, {"id": "ch06_short_2", "modI": 0, "q": "简述RNA-seq实验设计需考虑的主要问题。", "a": "1. 生物学重复：一般3~5个，假阳性控制要求高时可增加；2. 样本提取：控制干扰变量，注意提取时间和组织细胞控制，提取后及时冷冻保存；3. 测序深度：有参考基因组且不分析可变剪切或新转录本时每样本最少5M有效reads，鉴定新转录本或无参考基因组时增加，small RNA一般需30M以上有效匹配reads；4. 文库构建：链特异性文库保留方向信息，定量和可变剪切鉴别更准确但价格更高；5. 测序策略：单末端测序更快、价格低，一般足够定量；双末端测序有利于基因注释和转录本异构体发现。", "kp": "ch06_s0_3"}, {"id": "ch06_short_3", "modI": 0, "q": "简述RNA-seq文库制备的主要流程。", "a": "1. 选择感兴趣样本提取RNA；2. 采用PolyA富集或rRNA移除策略分离纯化RNA；3. 随机打碎成短片段并反转录为cDNA；4. 选择合适长度片段添加接头构建文库；5. 扩增并测序。cDNA文库制备关键步骤包括总RNA提取、RNA分离纯化、cDNA合成。", "kp": "ch06_s0_5"}, {"id": "ch06_short_4", "modI": 0, "q": "简述差异表达分析中差异的来源及处理效应检验的基本思路。", "a": "1. 不同实验处理引起的差异称为处理差异；2. 同一实验条件下不同样本之间由于个体差异、技术误差等存在差异，称为组内差异；3. 直接比较组间差异时包括组内差异和处理差异；4. 最终检验处理效应显著性时，应由组间差异减去组内差异；5. 计算组内差异需要生物学重复，无重复样本时差异表达分析结果可靠性下降。", "kp": "ch06_s0_9"}, {"id": "ch06_short_5", "modI": 0, "q": "简述常用差异表达分析模型及其适用性。", "a": "1. 高斯分布：最初用于描述表达水平，但基因表达量不可能是负值，严格意义上不符合正态分布；2. 泊松分布：技术重复条件下测序方差与泊松分布方差吻合，低表达基因方差符合泊松分布，但表达量升高后实际方差远大于泊松分布方差；3. 负二项分布：可调整散度因子α调节模型离散度，符合基因表达方差远大于均值的情况，DESeq和edgeR采用；4. β负二项分布：可拟合多重比对reads分配误差，与负二项分布结合，Cuffdiff采用。", "kp": "ch06_s0_11"}], "calc": [{"id": "ch06_calc_1", "modI": 0, "q": "论述RNA-seq数据分析中，有参考基因组和无参考基因组两种策略的主要流程差异，并说明各自常用工具。", "a": "有参考基因组时，RNA-seq核心分析通常包括序列比对和表达定量。可使用Bowtie、HISAT2、STAR等将reads比对到参考基因组或转录组；随后利用HTSeq-count或RSEM等进行reads计数并估算表达量；还可进行可变剪切、基因融合和差异表达分析。无参考基因组时，需先进行从头组装，如Trinity软件包含Inchworm、Chrysalis和Butterfly三个模块：Inchworm将reads切割为k-mers并延伸组装成contigs；Chrysalis将contigs聚类并构建de Bruijn图；Butterfly拆分de Bruijn图并依据reads和成对reads寻找最佳路径，得到具有可变剪切的全长转录本。组装完成后需评估质量，包括组装完整性、准确性及冗余度；再将reads通过Bowtie重新比对到组装转录本上，利用HTSeq-count或RSEM等计数估算表达量，并可通过Blast2GO等进行功能注释。", "steps": "1. 有参考基因组：比对到参考基因组/转录组；2. 常用比对工具：Bowtie、HISAT2、STAR；3. 定量工具：HTSeq-count、RSEM；4. 无参考基因组：从头组装；5. Trinity三模块：Inchworm、Chrysalis、Butterfly；6. 组装质量评估：完整性、准确性、冗余度；7. 重新比对与定量；8. 功能注释：Blast2GO等。", "kp": "ch06_s0_2"}, {"id": "ch06_calc_2", "modI": 0, "q": "结合案例，论述RNA-seq数据预处理与质控的主要步骤、常用命令参数及质控结果解读。", "a": "案例中RNA-seq数据预处理包括提取fastq文件、质量评估和质量控制。首先使用fastq-dump工具从SRA文件中提取fastq序列文件，如$ fastq-dump SRR3418005.sra &，对其余文件执行相同命令。然后使用FastQC检测原始测序数据质量，如$ fastqc -o ../fastqc_results -f fastq SRR3418005.fastq SRR3418006.fastq SRR3418019.fastq SRR3418020.fastq &，其中-o指定输出目录，-f指定输入格式。根据FastQC结果，Per base sequence quality评估为正常，而Per base sequence content显示约前12位碱基核酸比例失常。若测序质量要求较高，可使用FastX_Toolkit进行质量控制：使用fastx_trimmer截去reads前12位碱基，如$ fastx_trimmer -Q 33 -f 12 -i SRR3418005.fastq -o fastx_results/SRR3418005_trimmed.fastq &，其中-Q为Illumina编码转换，-f为截取起始位置，-i输入文件，-o输出文件；使用fastq_quality_filter过滤低质量reads，如$ fastq_quality_filter -Q 33 -q 20 -p 80 -i SRR3418005_trimmed.fastq -o SRR3418005_filtered.fastq &，其中-q为保留结果所需达到的最低得分，-p为每个reads中达到-q得分的最小百分数。处理后再次质量评估，Per base sequence content等指标提升，Sequence duplication levels和Kmer Content可能仍未达标，但已可用于RNA-seq分析。", "steps": "1. fastq-dump提取fastq；2. FastQC质量评估；3. 关键指标：Per base sequence quality、Per base sequence content；4. fastx_trimmer截去前12位碱基；5. 参数：-Q 33、-f、-i、-o；6. fastq_quality_filter过滤低质量reads；7. 参数：-q、-p；8. 处理后复评；9. 部分指标提升，部分未达标但可用于分析。", "kp": "ch06_s0_15"}], "term": [{"id": "ch06_term_1", "modI": 0, "term": "Central Dogma", "def": "由Crick于1958年提出，描述遗传信息从DNA经RNA传递至蛋白质的基本流向；对应三个组学层次：基因组学、转录组学和蛋白质组学。", "kp": "ch06_s0_15"}, {"id": "ch06_term_2", "modI": 0, "term": "Transcriptomics", "def": "20世纪90年代提出，在转录组水平研究基因表达；研究对象是全基因组尺度下所有转录本（transcriptome）。广义包括mRNA、rRNA、tRNA、ncRNA等，狭义常特指mRNA。", "kp": "ch06_s0_0"}, {"id": "ch06_term_3", "modI": 0, "term": "Transcriptome", "def": "细胞或组织中所有RNA分子的总和；包括mRNA、rRNA、tRNA、ncRNA等；本章无特殊说明时专指mRNA。", "kp": "ch06_s0_0"}, {"id": "ch06_term_4", "modI": 0, "term": "RNA-seq", "def": "基于第二代测序的转录组测序技术；不依赖参考基因组即可直接测定转录本序列和含量；通量高、成本日益降低；自2008年Nagalakshmi等用于酵母转录组研究后广泛应用。", "kp": "ch06_s0_2"}, {"id": "ch06_term_5", "modI": 0, "term": "Microarray", "def": "基于杂交的基因芯片技术；将荧光标记cDNA制成微阵列探针；通量较高、价格相对较低；但需参考转录组信息，存在交叉杂交背景噪声、低表达丰度基因检测困难、荧光信号动态范围有限等缺陷。", "kp": "ch06_s0_0"}, {"id": "ch06_term_6", "modI": 0, "term": "FASTQ", "def": "存储生物序列及其测序质量得分的文本格式；最初由Wellcome Trust Sanger研究所开发，用于捆绑FASTA序列及质量数据；现为高通量测序仪输出实际标准。每个read通常四行：@标识行、序列行、+行、质量得分行；质量行长度必须与序列行相同。", "kp": "ch06_s0_6"}, {"id": "ch06_term_7", "modI": 0, "term": "FastQC", "def": "用于检测原始测序数据质量的工具；关键指标包括Per base sequence quality、Per base sequence content等；用于RNA-seq数据预处理中的质量评估。", "kp": "ch06_s0_7"}, {"id": "ch06_term_8", "modI": 0, "term": "FastX_Toolkit", "def": "用于测序数据质量控制的工具集；常用fastx_trimmer截去reads前12位碱基，fastq_quality_filter过滤低质量reads；参数-Q 33用于Illumina编码转换。", "kp": "ch06_s0_7"}, {"id": "ch06_term_9", "modI": 0, "term": "Bowtie", "def": "短序列比对工具；有参考基因组时可将RNA-seq reads比对到参考基因组或转录组；组装后也可将reads重新比对到组装转录本上用于表达定量。", "kp": "ch06_s0_8"}, {"id": "ch06_term_10", "modI": 0, "term": "HISAT2", "def": "RNA-seq有参考基因组分析中的比对工具；可将reads比对到参考基因组或转录组，用于后续表达定量和可变剪切分析。", "kp": "ch06_s0_8"}, {"id": "ch06_term_11", "modI": 0, "term": "STAR", "def": "RNA-seq有参考基因组分析中的比对工具；可将reads比对到参考基因组或转录组；也常用于基因融合分析相关流程。", "kp": "ch06_s0_6"}, {"id": "ch06_term_12", "modI": 0, "term": "Trinity", "def": "无参考基因组时进行从头组装的软件；包含Inchworm、Chrysalis和Butterfly三个模块。Inchworm将reads切割为k-mers并延伸组装成contigs；Chrysalis聚类contigs并构建de Bruijn图；Butterfly拆分de Bruijn图并寻找最佳路径，得到具有可变剪切的全长转录本。", "kp": "ch06_s0_8"}], "preview": {"main": "本章主线：从中心法则和转录组学定义出发，介绍转录本测定技术演进，重点讲解 RNA-seq 的实验设计、平台选择、文库制备、FASTQ 数据格式、质控预处理、序列比对与表达定量、差异表达分析模型与工具、聚类与共表达网络、可变剪切与基因融合分析，并通过拟南芥 ABA 处理案例串联 RNA-seq 数据分析全流程。", "questions": ["转录组学与基因组学、蛋白质组学的关系是什么？为什么转录组学能弥补基因组学和蛋白质研究的不足？", "RNA-seq 相比基因芯片和早期 Sanger 测序技术有哪些关键优势？", "RNA-seq 实验设计中，生物学重复、测序深度、链特异性文库和单端/双端测序应如何权衡？", "RNA-seq 数据预处理、比对、表达定量和差异表达分析的主要步骤与常用工具有哪些？", "如何利用 RNA-seq 进行可变剪切、基因融合和多组学整合分析，并控制假阳性？"]}, "appcards": [{"front": "应用/分析题：为什么 RNA-seq 比基因芯片更适合发现新转录本和可变剪切异构体？", "back": "RNA-seq 不依赖参考基因组或参考转录组，可直接测定转录本序列和含量；通量高、动态范围由测序深度决定；能检测低丰度转录本、新转录本、可变剪切位点及异构体；链特异性文库还可保留转录本方向信息。基因芯片依赖已知参考转录组设计探针，存在交叉杂交、低丰度检测困难、动态范围受荧光信号限制等问题，难以发现新转录本和精确解析异构体。", "points": "不依赖参考序列；直接测序获得序列与含量；高通量；低丰度检测；新转录本；可变剪切/异构体；链特异性方向信息；对比芯片交叉杂交、动态范围有限、依赖参考转录组", "mod": 0, "modName": "第六章 转录组学", "level": "掌握", "src": "生成"}, {"front": "应用/分析题：设计一个真核 mRNA 的 RNA-seq 实验时，应如何考虑生物学重复、测序深度、文库类型和测序策略？", "back": "生物学重复一般 3~5 个，假阳性控制要求高时增加；样本提取需控制时间、组织细胞和干扰变量，提取后及时冷冻。测序深度：有参考基因组且不做可变剪切或新转录本分析时，每样本至少 5M 有效 reads（ENCODE 推荐）；鉴定新转录本或无参考基因组时适当增加；small RNA 通常需 30M 以上有效匹配 reads。文库构建：链特异性文库可保留转录本方向，避免互补链干扰，定量和可变剪切鉴别更准确，但价格更高。测序策略：单末端测序更快、价格低，一般足够定量；双末端测序产生成对 reads，有利于基因注释和转录本异构体发现。", "points": "重复 3~5 个；样本提取与保存；测序深度 5M/新转录本增加/small RNA 30M；链特异性文库；单端 vs 双端；结合实验目的选择", "mod": 0, "modName": "第六章 转录组学", "level": "掌握", "src": "生成"}, {"front": "应用/分析题：FASTQ 文件的基本格式是什么？在 RNA-seq 质控中 FastQC 和 FastX_Toolkit 通常如何使用？", "back": "FASTQ 用于存储核苷酸序列及其测序质量得分，每个 read 通常四行：第一行以 @ 开头，为序列标识符及描述；第二行为 read 序列；第三行以 + 开头，可再次添加描述；第四行为质量得分，与第二行等长，序列字母和质量得分均用单个 ASCII 字符表示。FastQC 用于原始测序数据质量评估，关键指标包括 Per base sequence quality、Per base sequence content 等。FastX_Toolkit 可用于质控：fastx_trimmer 截去 reads 前 12 位碱基，参数 -Q 33 为 Illumina 编码转换，-f 为截取起始位置，-i 输入，-o 输出；fastq_quality_filter 过滤低质量 reads，-q 为保留所需最低得分，-p 为每个 read 中达到 -q 得分的最小百分数。处理后再次质量评估，Per base sequence content 等可提升，但 Sequence duplication levels 和 Kmer Content 可能仍未达标。", "points": "FASTQ 四行结构；@、序列、+、质量；ASCII 质量得分；FastQC 指标；fastx_trimmer 参数；fastq_quality_filter 参数；处理后复评", "mod": 0, "modName": "第六章 转录组学", "level": "掌握", "src": "生成"}, {"front": "应用/分析题：RNA-seq 有参考基因组和无参考基因组时，序列比对与表达定量流程分别是什么？", "back": "有参考基因组时，可用 Bowtie、HISAT2、STAR 等将 reads 比对到参考基因组或转录组，然后进行表达定量。无参考基因组时，需从头组装，如 Trinity 包含 Inchworm、Chrysalis 和 Butterfly 三个模块：Inchworm 将 reads 切割为 k-mers，利用重叠延伸组装成 contigs；Chrysalis 将 contigs 聚类并构建 de Bruijn 图；Butterfly 拆分 de Bruijn 图，依据 reads 和成对 reads 寻找最佳路径，得到具有可变剪切的全长转录本。组装后评估完整性、准确性和冗余度；再将 reads 通过 Bowtie 回比到组装转录本，用 HTSeq-count 或 RSEM 等计数估算表达量，并可通过 Blast2GO 等进行功能注释。", "points": "有参考：Bowtie/HISAT2/STAR 比对；表达定量；无参考：Trinity 三模块；Inchworm k-mer 延伸；Chrysalis 聚类与 de Bruijn 图；Butterfly 找路径；组装评估；回比计数 HTSeq-count/RSEM；Blast2GO 注释", "mod": 0, "modName": "第六章 转录组学", "level": "掌握", "src": "生成"}, {"front": "应用/分析题：差异表达分析中为什么常用负二项分布？DESeq、edgeR、limma、Cuffdiff 等工具各有何特点？", "back": "RNA-seq reads 计数为离散数据，早期高斯分布不适合，因为表达量非负且不符合正态；泊松分布仅适合技术重复或低表达基因，生物学重复下表达量升高时实际方差远大于均值，泊松分布会低估个体差异。负二项分布通过散度因子 α 调节离散度，可拟合基因表达方差远大于均值的情况，DESeq 和 edgeR 均采用。β负二项分布可拟合多重比对 reads 分配误差，Cuffdiff 采用。工具比较：limma 在多数实验中表现良好且速度快；DESeq 和 edgeR 与 limma 在显著性排序上相似，但 FDR 控制可能偏宽松；SAMseq FDR 控制好但需 10 个以上重复；NOISeq/NOISeqBIO 可控制假阳性但牺牲灵敏度，适合重复数不同的情况；Cuffdiff/Cuffdiff2 可分析转录本水平差异，但受 reads 比对分配问题影响；EBSeq 等也可用于异构体水平分析；Next maSigPro、DyNB、Ballgown、EBSeq-HMM 可分析时间序列 RNA-seq。", "points": "高斯分布局限；泊松分布局限；负二项分布与散度因子；DESeq/edgeR；β负二项与 Cuffdiff；limma；SAMseq；NOISeq；Cuffdiff 问题；时间序列工具", "mod": 0, "modName": "第六章 转录组学", "level": "掌握", "src": "生成"}, {"front": "应用/分析题：RNA-seq 下游分析中，聚类分析、共表达网络、GO/Pathway 富集、可变剪切和基因融合分析分别解决什么问题？", "back": "聚类分析将表达模式相似的基因归为一类，推断功能或调控关系，常用层次聚类和 K-means。共表达网络基于表达相关性连接基因，识别模块和枢纽基因，WGCNA 通过相关系数加权构建无尺度网络，并将模块与表型关联。GO 和 Pathway 富集用于解释基因集功能，GO 包括生物学过程、分子功能和细胞组分三个本体，Pathway 常用 KEGG；富集分析通过超几何检验或 Fisher 精确检验计算显著性，并进行多重检验校正。可变剪切分析识别剪切位点和异构体表达水平，类型包括外显子跳跃、内含子保留、可变 5' 剪接位点、可变 3' 剪接位点和互斥外显子，常用 rMATS、Cufflinks、StringTie 等。基因融合分析检测染色体易位、缺失等引起的融合转录本，肿瘤研究中尤为重要，常用 STAR-Fusion、FusionCatcher、SOAPfuse 等，需结合跨断点 reads 和成对 reads 控制假阳性。RNA-seq 还可与全基因组测序、DNA 表观修饰、ChIP-seq、ncRNA、蛋白质组和代谢组等多组学结合，构建转录调控网络、mRNA-ncRNA 共表达网络、代谢网络等。", "points": "聚类：层次/K-means；共表达网络/WGCNA；GO 三本体；KEGG Pathway；超几何/Fisher 检验与校正；可变剪切类型与工具；基因融合工具与假阳性控制；多组学整合", "mod": 0, "modName": "第六章 转录组学", "level": "掌握", "src": "生成"}]};